/* Ajustes y servicios iniciales (lo que hacía setup()): se completan solos si faltan */
function ensureSeed_() {
  const have = readTable_('Ajustes').map((r) => r.clave);
  DEFAULT_SETTINGS.filter((x) => have.indexOf(x[0]) < 0).forEach((x) => appendRow_('Ajustes', { clave: x[0], valor: x[1], 'qué es': x[2] }));
  const rows = readTable_('Servicios');
  if (!rows.length) {
    DEFAULT_SERVICES.forEach((x) => appendRow_('Servicios', {
      id: x[0], nombre: x[1], duracionMin: x[2], precioRD: x[3], precioDesde: x[4], activo: x[5],
      volverDias: x[6], depositoPct: x[7], retoqueDias: x[8], consentimiento: x[9],
      categoriaId: x[0], tipo: 'servicio', padreId: '', orden: 0, descripcion: '',
    }));
  } else {
    rows.forEach((r) => {
      const def = DEFAULT_SERVICES.filter((x) => x[0] === r.id)[0];
      const patch: any = {};
      if (!r.categoriaId) patch.categoriaId = ['faciales', 'cejas', 'pestanas', 'micropigmentacion', 'depilacion'].includes(r.id) ? r.id : 'otros';
      if (!r.tipo) patch.tipo = 'servicio';
      if (!r.volverDias) patch.volverDias = def ? def[6] : 30;
      if (r.retoqueDias === '') patch.retoqueDias = def ? def[8] : 0;
      if (r.consentimiento === '') patch.consentimiento = def ? def[9] : 'no';
      if (Object.keys(patch).length) updateTable_('Servicios', r._row, patch);
    });
  }
  resetCaches_();
}

/* Programa las tareas automáticas en pg_cron si aún no lo están (al abrir el panel) */
async function ensureCron_(tx: any) {
  const c = cx();
  // En un punto de guardado: si pg_cron no está (por ejemplo, en pruebas locales) no se pierde la transacción
  try { await tx.savepoint(async (sp: any) => { const r = await sp`select public.majobella_tareas_programadas() as on`; c.cronActive = !!r[0].on; }); }
  catch (e) { c.cronActive = null; return; }
  const key = env_('CRON_KEY'), base = env_('SUPABASE_URL');
  if (c.cronActive || !key || !base) return;
  try {
    await tx.savepoint(async (sp: any) => { await sp`select public.majobella_programar_tareas(${base.replace(/\/$/, '') + '/functions/v1/api'}, ${key})`; });
    c.cronActive = true;
  } catch (e) { logError_('automatizacion', 'No se pudieron programar las tareas automáticas: ' + msg_(e), '', ''); }
}

function urgentMail_(text: string, ref: string) {
  let s: any = {};
  try { s = settings_(); } catch (e) { s = {}; }
  const to = adminTo_(s);
  if (!to) return;
  const html = layout_(s, { kicker: 'Aviso del sistema', title: ERROR_TITLES.pago, intro: esc_(text), details: ref ? [['Referencia', esc_(ref)]] : [], note: 'Este aviso es importante: revísalo hoy.' });
  cx().out.push({ kind: 'mail', mail: { to, subject: '⚠ MAJOBELLA · ' + ERROR_TITLES.pago, html, text: plainText_(html), log: null, ref } });
}
function safeOutbox(sql: any) { return runOutbox(sql).catch((e) => console.error('Error al enviar:', msg_(e))); }

export interface ApiResult { status: number; body: any; after?: Promise<void> }

/* Ejecuta una acción. method: 'GET' | 'POST'; data: parámetros o cuerpo; headers: cabeceras (minúsculas) */
export async function handle(deps: Deps, method: string, data: any, headers: Record<string, string> = {}): Promise<ApiResult> {
  const c = newCtx(deps);
  return runWith(c, async () => {
    const sql = deps.sql;
    const action = String((data && data.action) || '');
    try {
      if (method === 'GET') {
        if (action === 'catalog') {
          const body = await sql.begin(async (tx: any) => {
            await loadTables(tx, { tables: ['Ajustes', 'Categorias', 'Servicios', 'Promociones', 'Paquetes', 'Galeria', 'Resenas', 'Cuentas'] });
            ensureSeed_();
            heartbeat_();
            const out = catalog_();
            await commit(tx);
            return out;
          });
          return { status: 200, body, after: safeOutbox(sql) };
        }
        if (action === 'busy' || action === 'availability') {
          const from = data.from || data.date, to = data.to || data.date;
          const body = await sql.begin(async (tx: any) => {
            await loadTables(tx, { tables: ['Reservas', 'Bloqueos', 'Ajustes'], reservasRange: /^\d{4}-\d{2}-\d{2}$/.test(from) && /^\d{4}-\d{2}-\d{2}$/.test(to) ? { from, to } : undefined });
            return action === 'busy' ? busyWithUntil_(from, to) : busy_(from, to);
          });
          return { status: 200, body };
        }
        return { status: 200, body: { ok: false, error: 'Acción no válida.' } };
      }

      // Tareas automáticas (las llama pg_cron cada hora con su clave)
      if (action === 'cron') {
        const key = env_('CRON_KEY');
        if (!key || headers['x-cron-key'] !== key) return { status: 401, body: { ok: false, error: 'No autorizado.' } };
        const body = await sql.begin(async (tx: any) => {
          await tx`select pg_advisory_xact_lock(${LOCK_KEY})`;
          await tx`delete from public.cache where vence < now()`;
          await loadTables(tx);
          ensureSeed_();
          const out = runAutomations_();
          await commit(tx);
          return { ok: true, result: out };
        });
        return { status: 200, body, after: safeOutbox(sql) };
      }

      const entry = ACTIONS[action];
      if (!entry) return { status: 200, body: { ok: false, error: 'Acción no válida.' } };
      const panel = PANEL.includes(action);

      const body = await sql.begin(async (tx: any) => {
        if (entry.lock) await tx`select pg_advisory_xact_lock(${LOCK_KEY})`;
        await loadTables(tx, panel ? { tables: undefined } : {});
        if (panel) await loadTables(tx, { tables: ['Correos', 'Errores'] });
        if (EXTRA[action]) await loadTables(tx, { tables: EXTRA[action] });
        ensureSeed_();
        // Verificaciones que necesitan internet, antes de la lógica
        if (data.idToken) { c.userToken = String(data.idToken); c.user = await resolveUser(c.userToken); }
        if (data.captcha) c.captcha = await resolveCaptcha(data, settings_());
        const extra: any = {};
        if (panel && c.user && adminEmails_().includes(c.user.email)) { extra.folder = await storagePrivacy(); await ensureCron_(tx); }
        const mark = c.ops.length, markOut = c.out.length;
        let out: any;
        try { out = await entry.fn(data, extra); }
        catch (err) {
          // Lo que la acción dejó a medias no se guarda; solo el aviso del error
          c.ops.length = mark; c.out.length = markOut;
          const m = msg_(err);
          if (!/sesión expiró|no tiene acceso/i.test(m)) logError_('sistema', m, data.id || '', 'acción: ' + action);
          out = { ok: false, error: m };
        }
        await commit(tx);
        // En las apps no hay cuadro de "no soy un robot": se pide iniciar sesión
        if (out && out.ok === false && out.error === NOT_HUMAN && data.app) out.error = 'Para continuar desde la app, inicia sesión con tu correo (Cuenta → Iniciar sesión).';
        return out;
      });
      return { status: 200, body, after: safeOutbox(sql) };
    } catch (err) {
      // No se pudo guardar. Si en esta petición se cobró algo, se avisa de inmediato para revisarlo a mano.
      const m = msg_(err);
      if (c.captures.length) {
        const text = 'Se cobró en PayPal (' + c.captures.join(', ') + ') pero no se pudo guardar: ' + m + '. Revisa la venta en PayPal y regístrala a mano.';
        try {
          await sql`insert into public.errores (fecha, tipo, mensaje, ref, detalle, avisado) values (now(), 'pago', ${text}, ${String(data.id || '').slice(0, 80)}, ${'acción: ' + action}, now())`;
        } catch (e) { /* nada */ }
        // Los correos de la acción no salen (no se guardó); solo el aviso urgente al estudio
        c.out = [];
        try { urgentMail_(text, String(data.id || '')); await runOutbox(sql); } catch (e) { /* nada */ }
        return { status: 200, body: { ok: false, error: 'Recibimos tu pago, pero hubo un problema al registrarlo. Ya nos llegó el aviso y te contactaremos. Guarda este código: ' + (data.id || '') } };
      }
      console.error('Error en', action, m);
      return { status: 200, body: { ok: false, error: /could not|connect|timeout|ECONN/i.test(m) ? 'El sistema está ocupado. Inténtalo de nuevo en un momento.' : m } };
    }
  });
}

/* MAJOBELLA · Tareas automáticas (cada hora, con pg_cron): recordatorios, pedir reseña, retoques,
   cumpleaños, lista de espera y aviso de transferencias sin revisar */
import { cx } from './ctx.ts';
import { appendRow_, readOpt_, readTable_, sysGet, sysSet, updateTable_ } from './db.ts';
import { rows_, servicesMap_, settings_, updateRow_ } from './data.ts';
import { codeTaken_ } from './pricing.ts';
import { checkWaitlist_ } from './waitlist.ts';
import { logError_ } from './errors.ts';
import { needAdmin_ } from './security.ts';
import { adminTo_, layout_, mailBirthday_, mailRetouch_, mailReminder_, mailReview_, mailUrl_, safeMail_ } from './mail.ts';
import { TZ } from './constants.ts';
import { addDaysKey_, clientKey_, esc_, fmtDate, monthDay_, money_, msg_, num_, on_, randCode_, safeJson_, strip_, todayKey_, uuid, whenText_ } from './util.ts';

export function runAutomations_() {
  const s = settings_();
  const now = new Date();
  const hour = Number(fmtDate(now, TZ, 'H'));
  const daytime = hour >= 8 && hour < 21;
  const out: any = { recordatorios: 0, resenas: 0, retoques: 0, cumpleanos: 0, espera: 0 };
  const rows = rows_();
  const step = function (key, fn) { try { out[key] = fn(); } catch (e) { out[key] = 'error: ' + msg_(e); logError_('automatizacion', key + ': ' + msg_(e), '', ''); } };
  if (on_(s.recordatorioActivo) && hour >= 7 && hour < 22) step('recordatorios', function () { return sendReminders_(rows, s, now); });
  if (daytime && on_(s.resenaActiva) && s.googleResenaUrl) step('resenas', function () { return askReviews_(rows, s, now); });
  if (daytime && on_(s.retoqueActivo)) step('retoques', function () { return retouchNotices_(rows, s); });
  if (daytime && on_(s.cumpleActivo)) step('cumpleanos', function () { return birthdays_(rows, s); });
  if (on_(s.esperaActiva)) step('espera', function () { return checkWaitlist_(s, null); });
  if (hour >= 8 && hour < 22) step('transferencias', function () { return nagTransfers_(rows, s, now); });
  sysSet('LAST_AUTO', JSON.stringify({ at: now.toISOString(), out: out }));
  return out;
}

export function automationStatus_() {
  return { lastRun: safeJson_(sysGet('LAST_AUTO'), null), trigger: cx().cronActive, quota: null };
}

/* Recordatorio X horas antes (una vez por cita) */
export function sendReminders_(rows, s, now) {
  const H = num_(s.recordatorioHoras, 24);
  let n = 0;
  rows.forEach(function (r) {
    if (r.estado !== 'confirmada' || r.recordatorio || !r.correo) return;
    const hoursLeft = (new Date(r.inicio).getTime() - now.getTime()) / 3600000;
    const age = (now.getTime() - new Date(r.creada || r.depositoPagado || 0).getTime()) / 3600000;
    if (hoursLeft > H || hoursLeft < 1 || age < 6) return;
    const m = mailReminder_(r, s);
    if (safeMail_(r.correo, m.subject, m.html, { tipo: 'recordatorio', ref: r.id })) { updateRow_(r._row, { recordatorio: now.toISOString() }); n++; }
  });
  return n;
}

/* Pedir reseña unas horas después de una cita realizada (una vez cada 120 días por clienta) */
export function askReviews_(rows, s, now) {
  const H = Math.max(0, Number(String(s.resenaHoras).replace(',', '.')) || 0);
  const lastAsked: any = {};
  rows.forEach(function (r) { if (r.resenaPedida && /^\d{4}-/.test(r.resenaPedida)) { const k = clientKey_(r.correo, r.telefono, r.clienta); if (!lastAsked[k] || r.resenaPedida > lastAsked[k]) lastAsked[k] = r.resenaPedida; } });
  let n = 0;
  rows.forEach(function (r) {
    if (r.estado !== 'completada' || r.resenaPedida || !r.correo) return;
    const end = new Date(r.fin).getTime();
    if (now.getTime() < end + H * 3600000 || now.getTime() > end + 7 * 86400000) return;
    const k = clientKey_(r.correo, r.telefono, r.clienta);
    if (lastAsked[k] && now.getTime() - new Date(lastAsked[k]).getTime() < 120 * 86400000) { updateRow_(r._row, { resenaPedida: 'no (pedida hace poco)' }); return; }
    const m = mailReview_(r, s);
    if (safeMail_(r.correo, m.subject, m.html, { tipo: 'resena', ref: r.id })) { updateRow_(r._row, { resenaPedida: now.toISOString() }); lastAsked[k] = now.toISOString(); n++; }
  });
  return n;
}

/* Aviso de retoque una semana antes de la fecha ideal (días por servicio en "Servicios") */
export function retouchNotices_(rows, s) {
  const svcs = servicesMap_();
  const today = todayKey_();
  let n = 0;
  rows.forEach(function (r) {
    if (r.estado !== 'completada' || r.retoqueAviso || !r.correo) return;
    const ids = safeJson_(r.serviciosJson, []).map(function (x) { return x.id; });
    const svc = ids.map(function (id) { return svcs[id]; }).filter(function (x) { return x && x.retoqueDays > 0; })[0];
    if (!svc) return;
    const ideal = addDaysKey_(r.fecha, svc.retoqueDays);
    if (today < addDaysKey_(ideal, -7)) return;
    const k = clientKey_(r.correo, r.telefono, r.clienta);
    const booked = rows.some(function (x) {
      return x.id !== r.id && x.fecha > r.fecha && ['confirmada', 'completada', 'retenida'].indexOf(x.estado) >= 0 &&
        clientKey_(x.correo, x.telefono, x.clienta) === k && safeJson_(x.serviciosJson, []).some(function (y) { return y.id === svc.id; });
    });
    if (booked) { updateRow_(r._row, { retoqueAviso: 'no (ya reservó)' }); return; }
    if (today > addDaysKey_(ideal, 21)) { updateRow_(r._row, { retoqueAviso: 'no (pasó la fecha)' }); return; }
    const m = mailRetouch_(r, s, svc, ideal);
    if (safeMail_(r.correo, m.subject, m.html, { tipo: 'retoque', ref: r.id })) { updateRow_(r._row, { retoqueAviso: new Date().toISOString() }); n++; }
  });
  return n;
}

/* Cumpleaños: código de un solo uso con el % de Ajustes */
export function birthdays_(rows, s) {
  const today = todayKey_();
  const md = today.slice(5);
  const year = today.slice(0, 4);
  let n = 0;
  readOpt_('Clientas').forEach(function (c) {
    if (monthDay_(c.cumpleanos) !== md || String(c.cumpleEnviado) === year) return;
    let email = c.correo;
    if (!email) {
      const last = rows.filter(function (r) { return r.correo && clientKey_(r.correo, r.telefono, r.clienta) === c.clave; }).pop();
      email = last ? last.correo : '';
    }
    if (!email) return;
    const pct = num_(s.cumpleDescuento, 15);
    const until = addDaysKey_(today, num_(s.cumpleDias, 30));
    let code = '';
    for (let i = 0; i < 6 && (!code || codeTaken_(code)); i++) code = 'CUMPLE-' + randCode_(5);
    appendRow_('Promociones', {
      id: 'PRM-' + uuid().slice(0, 6).toUpperCase(), nombre: 'Cumpleaños de ' + (c.nombre || 'clienta'), tipo: 'codigo', codigo: code,
      servicios: 'todos', descuentoTipo: 'porcentaje', valor: pct, desde: today, hasta: until, usosMax: 1, usos: 0, activo: 'si', creada: new Date().toISOString(),
    });
    const m = mailBirthday_(c.nombre, s, code, pct, until);
    safeMail_(email, m.subject, m.html, { tipo: 'cumpleanos', ref: c.clave });
    updateTable_('Clientas', c._row, { cumpleEnviado: year });
    n++;
  });
  return n;
}

/* Recuerda al estudio las transferencias sin revisar (como mucho cada 4 horas) */
export function nagTransfers_(rows, s, now) {
  const pending = rows.filter(function (r) { return r.estado === 'por-confirmar' && now.getTime() - new Date(r.comprobanteEn || r.creada).getTime() > 2 * 3600000; });
  if (!pending.length) return 0;
  const last = Number(sysGet('TRANSFER_NAG') || 0);
  if (now.getTime() - last < 4 * 3600000) return 0;
  sysSet('TRANSFER_NAG', String(now.getTime()));
  const html = layout_(s, {
    kicker: 'Transferencias por revisar', title: pending.length === 1 ? 'Tienes 1 transferencia sin revisar' : 'Tienes ' + pending.length + ' transferencias sin revisar',
    intro: 'Estas clientas subieron su comprobante y esperan tu confirmación. Su horario sigue apartado.',
    details: pending.slice(0, 10).map(function (r) { return [r.clienta, esc_(whenText_(r)) + '<br>Depósito RD$ ' + money_(r.depositoRD)]; }),
    cta: { text: 'Revisar en el dashboard', url: mailUrl_(s, 'admin.html#agenda') },
  });
  safeMail_(adminTo_(s), 'Transferencias por revisar (' + pending.length + ') · MAJOBELLA', html, { tipo: 'aviso', ref: 'transferencias' });
  return pending.length;
}

export function adminRunAutomations_(d) {
  needAdmin_(d);
  const out = runAutomations_();
  return { ok: true, result: out, automation: automationStatus_(), emails: readOpt_('Correos').slice(-200).reverse().map(strip_) };
}

/* MAJOBELLA · Reservas de las clientas: apartar, pagar el depósito, consultar, cancelar, cambiar la fecha,
   pagar el saldo y subir el comprobante de una transferencia */
import { cx } from './ctx.ts';
import { appendRow_, readTable_, updateTable_ } from './db.ts';
import { catalogItems_, findRow_, rows_, settings_, settingsCached_, updateRow_ } from './data.ts';
import { conflicts_, schedule_, slotProblem_ } from './schedule.ts';
import { applyBono_, applyGift_, loyaltyFor_, pricing_, pricingOut_, usePromo_ } from './pricing.ts';
import { changesMax_, refundPending_, transferInfo_ } from './catalog.ts';
import { appContext_, approveUrl_, firstCapture_, orderBody, paypal_, tryRefund_ } from './paypal.ts';
import { authorized_, human_, limited_, noteFail_, verifyIdToken_ } from './security.ts';
import { calendarCancel_, calendarCreate_, calendarMove_ } from './google.ts';
import { adminTo_, mailAdminRescheduled_, mailAdminTransfer_, mailTransferReceived_, notifyCancelled_, notifyConfirmed_, notifyRescheduled_, safeMail_ } from './mail.ts';
import { consentState_ } from './consent.ts';
import { evaluateConsent_ } from './consent-templates.ts';
import { markWaitlistBooked_, notifyWaitlist_ } from './waitlist.ts';
import { logError_ } from './errors.ts';
import { PRIVATE_BUCKET, filePath, putFile } from './storage.ts';
import { NOT_HUMAN, TOO_MANY, TZ, UTC_OFFSET } from './constants.ts';
import { b64ToBytes, clean_, clientKey_, client_, fmtDate, hash_, isDateKey_, monthDay_, msg_, normCode_, num_, safeJson_, todayKey_, usd_, uuid, whenText_ } from './util.ts';

export async function hold_(d) {
  const s = settings_();
  const sch = schedule_(s);
  const c = d.client || {};
  const cv = client_(c, true);
  if (!cv.ok) return { ok: false, error: cv.error };
  const name = cv.name, phone = cv.phone, notes = cv.notes;
  let email = cv.email;
  if (d.idToken) { const u = verifyIdToken_(d.idToken); if (u) email = u.email; }
  if (!human_(d, s)) return { ok: false, error: NOT_HUMAN };
  if (limited_(d)) return { ok: false, error: TOO_MANY };
  const method = d.method === 'transferencia' ? 'transferencia' : 'paypal';
  const tf = method === 'transferencia' ? transferInfo_(s) : null;
  if (tf && !tf.enabled) return { ok: false, error: 'El pago por transferencia no está disponible ahora. Elige PayPal o escríbenos.' };

  // Servicios y precios desde la hoja (nunca desde el navegador)
  const ids = (d.services || []).map(function (x) { return typeof x === 'string' ? x : x && x.id; }).filter(Boolean);
  const items = catalogItems_(ids);
  if (!items.length || items.some(function (x) { return !x; })) return { ok: false, error: 'Elige un servicio válido.' };
  const consentSnapshots = evaluateConsent_(items, d);
  const minutes = items.reduce(function (t, x) { return t + x.durationMinutes; }, 0);

  // Horario
  if (!isDateKey_(d.date) || !/^\d{2}:\d{2}$/.test(d.time || '')) return { ok: false, error: 'Fecha u hora no válida.' };
  const check = slotProblem_(sch, d.date, d.time, minutes);
  if (check) return { ok: false, error: check };
  const start = new Date(d.date + 'T' + d.time + ':00' + UTC_OFFSET);
  const end = new Date(start.getTime() + minutes * 60000);
  if (conflicts_(start, end, null).length) return { ok: false, error: 'Ese horario acaba de reservarse. Elige otro, por favor.' };

  // Montos con promociones y tarjeta de regalo
  const p = pricing_(items, d.code, d.giftCode, { email: email, phone: phone });
  if ((normCode_(d.code) && p.codeStatus === 'invalid') || (normCode_(d.giftCode) && p.giftStatus === 'invalid')) noteFail_(d);
  if (normCode_(d.code) && p.codeStatus === 'invalid') return { ok: false, error: 'Ese código de descuento no es válido o ya venció.' };
  if (normCode_(d.giftCode) && p.giftStatus === 'invalid') return { ok: false, error: 'Esa tarjeta o paquete no es válido o no tiene saldo.' };
  if (normCode_(d.giftCode) && p.giftStatus === 'notApplicable') return { ok: false, error: 'Ese paquete es para otro servicio.' };

  const holdMin = num_(s.minutosRetencion, 15);
  const id = 'MJB-' + fmtDate(start, TZ, 'yyMMdd') + '-' + uuid().slice(0, 6).toUpperCase();
  const token = uuid();
  const row: any = {
    id: id, creada: new Date().toISOString(), estado: 'retenida',
    fecha: d.date, hora: d.time, inicio: start.toISOString(), fin: end.toISOString(), duracionMin: minutes,
    servicios: items.map(function (x) { return x.name; }).join(' + '),
    serviciosJson: JSON.stringify(items.map(function (x) { return { id: x.id, name: x.name, price: x.price, durationMinutes: x.durationMinutes }; })),
    subtotalRD: p.subtotal, descuentoRD: p.discount, promoId: p.promo ? p.promo.id : '', codigo: p.codeStatus === 'ok' ? normCode_(d.code) : '',
    giftCodigo: p.gift ? p.gift.codigo : '', giftRD: p.gift ? p.giftApplied : 0,
    bonoCodigo: p.bono ? p.bono.codigo : '', bonoRD: p.bono ? p.giftApplied : 0, fidelidad: p.loyalApplied ? 'si' : '',
    cumpleanos: monthDay_(c.birthday), firmaToken: uuid().replace(/-/g, '').slice(0, 20),
    totalRD: p.total, depositoRD: p.depositRD, depositoUSD: p.depositUSD.toFixed(2), saldoRD: p.balanceRD,
    clienta: name, telefono: phone, correo: email, nota: notes, tokenHash: hash_(token),
    saldoEstado: p.balanceRD > 0 ? 'pendiente' : 'pagado', retenidaHasta: new Date(Date.now() + holdMin * 60000).toISOString(),
    consentimientosJson: consentSnapshots.length?JSON.stringify(consentSnapshots):'',
    consentimiento: consentSnapshots.length?new Date().toISOString():'',
    origen: clean_(d.origen, 40), canal: clean_(d.canal, 80), creadaPor: 'web',
  };

  // La tarjeta de regalo cubre todo el depósito: se confirma sin PayPal
  if (p.depositRD <= 0) {
    row.estado = 'confirmada';
    row.metodoDeposito = p.bono ? 'paquete' : (p.giftApplied ? 'tarjeta de regalo' : '');
    row.depositoPagado = new Date().toISOString();
    row.retenidaHasta = '';
    applyGift_(row, -1);
    applyBono_(row, -1);
    saveBirthday_(row);
    markWaitlistBooked_(row);
    usePromo_(row.promoId);
    row.eventoId = calendarCreate_(row, s);
    appendRow_('Reservas', row);
    notifyConfirmed_(row, s);
    return { ok: true, id: id, manageToken: token, confirmed: true, appointment: publicRow_(row), pricing: pricingOut_(p) };
  }

  // Transferencia: se aparta el horario mientras la clienta sube el comprobante
  if (tf) {
    const until = Math.min(Date.now() + tf.minutes * 60000, start.getTime() - 30 * 60000);
    row.metodoDeposito = 'transferencia';
    row.retenidaHasta = new Date(Math.max(until, Date.now() + 10 * 60000)).toISOString();
    appendRow_('Reservas', row);
    return {
      ok: true, id: id, manageToken: token, transfer: true, accounts: tf.accounts,
      totalRD: p.total, depositRD: p.depositRD, balanceRD: p.balanceRD, expiresAt: row.retenidaHasta, pricing: pricingOut_(p),
    };
  }

  // Orden de PayPal por el depósito
  const order = await paypal_('post', '/v2/checkout/orders', {
    intent: 'CAPTURE',
    purchase_units: [{
      reference_id: id, custom_id: id, invoice_id: id + '-D',
      description: ('Depósito · ' + row.servicios).slice(0, 127),
      amount: { currency_code: 'USD', value: p.depositUSD.toFixed(2) },
    }],
    application_context: appContext_(d, s),
  }, id + '-order');
  row.paypalOrden = order.id;
  row.metodoDeposito = 'paypal';
  appendRow_('Reservas', row);

  return {
    ok: true, id: id, manageToken: token, orderId: order.id, approveUrl: approveUrl_(order),
    totalRD: p.total, depositRD: p.depositRD, depositUSD: p.depositUSD.toFixed(2), balanceRD: p.balanceRD,
    usdRate: p.usdRate, expiresAt: row.retenidaHasta, pricing: pricingOut_(p),
  };
}

export async function capture_(d) {
  const found = findRow_(d.id);
  if (!found) return { ok: false, error: 'No encontramos la reserva.' };
  const r = found.row;
  if (r.paypalOrden !== d.orderId) return { ok: false, error: 'El pago no corresponde a esta reserva.' };
  if (r.estado === 'confirmada' && r.paypalCaptura) return { ok: true, appointment: publicRow_(r) };
  if (r.estado !== 'retenida' && r.estado !== 'expirada') return { ok: false, error: 'Esta reserva ya no está disponible.' };

  const result = await paypal_('post', '/v2/checkout/orders/' + encodeURIComponent(d.orderId) + '/capture', {}, r.id + '-capture');
  const cap = firstCapture_(result);
  if (!cap || cap.status !== 'COMPLETED') return { ok: false, error: 'PayPal no completó el pago. No se te cobró.' };
  if (cap.amount.currency_code !== 'USD' || Number(cap.amount.value) + 0.001 < Number(r.depositoUSD)) {
    return { ok: false, error: 'El monto pagado no coincide con el depósito. Escríbenos por WhatsApp.' };
  }

  const patch: any = { paypalCaptura: cap.id, depositoPagado: new Date().toISOString() };
  // Si la retención venció y otra persona tomó el horario, se devuelve el dinero
  const start = new Date(r.inicio), end = new Date(r.fin);
  if (conflicts_(start, end, r.id).length) {
    const refund = await tryRefund_(cap.id, r.id + '-conflict');
    patch.estado = 'cancelada'; patch.canceladaEn = new Date().toISOString(); patch.canceladaPor = 'sistema: horario ocupado';
    patch.reembolso = refund;
    updateRow_(found.index, patch);
    return { ok: false, error: /^reembolsado/.test(refund)
      ? 'El horario se ocupó mientras pagabas. Se solicitó el reembolso de tu depósito en PayPal.'
      : 'El horario se ocupó mientras pagabas. Tu reembolso está pendiente de revisión por el estudio. Guarda este código: ' + r.id };
  }

  patch.estado = 'confirmada';
  try {
    updateRow_(found.index, { paypalCaptura: cap.id, depositoPagado: patch.depositoPagado }); // primero queda anotado el cobro
    confirmPaid_(found.index, r, patch);
  } catch (err) {
    return paidButFailed_('el depósito de la reserva ' + r.id, cap.id, r.id, err);
  }
  notifyConfirmed_(r, settings_());
  return { ok: true, appointment: publicRow_(r) };
}

/* Deja confirmada una cita ya pagada: descuenta tarjeta/paquete, promoción, cumpleaños, lista de espera y calendario */
export function confirmPaid_(index, r, patch) {
  Object.keys(patch).forEach(function (k) { r[k] = patch[k]; });
  const s = settings_();
  applyGift_(r, -1);
  applyBono_(r, -1);
  usePromo_(r.promoId);
  saveBirthday_(r);
  markWaitlistBooked_(r);
  patch.saldoRD = r.saldoRD;
  patch.saldoEstado = r.saldoEstado;
  patch.giftRD = r.giftRD;
  patch.eventoId = calendarCreate_(r, s);
  r.eventoId = patch.eventoId;
  updateRow_(index, patch);
}

/* El cobro se hizo pero algo falló después: se avisa de inmediato para revisarlo a mano */
export function paidButFailed_(what, captureId, ref, err) {
  logError_('pago', 'Se cobró ' + what + ' (PayPal ' + captureId + '), pero hubo un error al guardarlo: ' + msg_(err) + '. Revisa la venta en PayPal y regístrala a mano.', ref, '', true);
  return { ok: false, error: 'Recibimos tu pago, pero hubo un problema al registrarlo. Ya nos llegó el aviso y te contactaremos. Guarda este código: ' + ref };
}

/* La clienta cerró PayPal sin pagar: se libera el horario */
export function release_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: true };
  if (found.row.estado === 'retenida') updateRow_(found.index, { estado: 'expirada' });
  return { ok: true };
}

export async function balanceOrder_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: false, error: 'No encontramos esa cita.' };
  const r = found.row;
  if (r.estado !== 'confirmada' && r.estado !== 'completada') return { ok: false, error: 'Esta cita no tiene saldo por pagar.' };
  if (r.saldoEstado === 'pagado' || !(Number(r.saldoRD) > 0)) return { ok: false, error: 'El saldo ya está pagado.' };
  if (new Date(r.inicio).getTime() > Date.now() + 15 * 60000) return { ok: false, error: 'El saldo se paga al terminar tu cita.' };
  const rate = num_(settings_().tasaUSD, 63);
  const amount = usd_(Number(r.saldoRD), rate);
  const order = await paypal_('post', '/v2/checkout/orders', {
    intent: 'CAPTURE',
    purchase_units: [{
      reference_id: r.id, custom_id: r.id, invoice_id: r.id + '-S-' + Date.now(),
      description: ('Saldo · ' + r.servicios).slice(0, 127),
      amount: { currency_code: 'USD', value: amount.toFixed(2) },
    }],
    application_context: appContext_(d, settings_()),
  });
  updateRow_(found.index, { saldoOrden: order.id, saldoUSD: amount.toFixed(2) });
  return { ok: true, orderId: order.id, approveUrl: approveUrl_(order), balanceUSD: amount.toFixed(2), balanceRD: Number(r.saldoRD) };
}

export async function balanceCapture_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: false, error: 'No encontramos esa cita.' };
  const r = found.row;
  if (r.saldoEstado === 'pagado') return { ok: true, appointment: publicRow_(r) };
  if (r.saldoOrden !== d.orderId) return { ok: false, error: 'El pago no corresponde a esta cita.' };
  const cap = firstCapture_(await paypal_('post', '/v2/checkout/orders/' + encodeURIComponent(d.orderId) + '/capture', {}, r.id + '-saldo-' + d.orderId));
  if (!cap || cap.status !== 'COMPLETED') return { ok: false, error: 'PayPal no completó el pago.' };
  // El monto lo fijó el servidor al crear la orden; nunca marcar pagado un cobro inferior.
  if (cap.amount?.currency_code !== 'USD' || !Number.isFinite(Number(cap.amount?.value)) ||
      Number(cap.amount.value) + 0.001 < Number(r.saldoUSD)) {
    return paidButFailed_('un importe diferente al saldo esperado de la cita ' + r.id,
      cap.id, r.id, new Error('Monto o moneda de PayPal no coincide con la orden registrada'));
  }
  const patch: any = { saldoEstado: 'pagado', saldoMetodo: 'paypal', saldoPagado: new Date().toISOString(), saldoCaptura: cap.id };
  try { updateRow_(found.index, patch); } catch (err) { return paidButFailed_('el saldo de la cita ' + r.id, cap.id, r.id, err); }
  Object.keys(patch).forEach(function (k) { r[k] = patch[k]; });
  return { ok: true, appointment: publicRow_(r) };
}

export function myAppointments_(d) {
  const u = verifyIdToken_(d.idToken);
  if (!u) return { ok: false, error: 'Tu sesión expiró. Vuelve a iniciar sesión.' };
  const now = Date.now();
  const items = rows_().filter(function (r) {
    if (r.correo !== u.email || r.estado === 'expirada' || r.estado === 'bloqueo') return false;
    return r.estado !== 'retenida' || (r.metodoDeposito === 'transferencia' && new Date(r.retenidaHasta).getTime() > now);
  }).map(publicRow_);
  return { ok: true, items: items, loyalty: loyaltyFor_({ email: u.email }, settings_()) };
}

/* Citas reservadas como invitada: la web guarda id + clave de gestión */
export function lookup_(d) {
  const want = (d.items || []).slice(0, 50);
  const all = rows_();
  const items = [];
  want.forEach(function (w) {
    const r = all.filter(function (x) { return x.id === w.id; })[0];
    if (r && w.token && r.tokenHash === hash_(w.token)) items.push(publicRow_(r));
  });
  return { ok: true, items: items };
}

export async function cancel_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: false, error: 'No encontramos esa cita.' };
  const r = found.row;
  if (r.estado !== 'confirmada' && r.estado !== 'por-confirmar') return { ok: false, error: 'Esta cita ya no se puede cancelar.' };
  const s = settings_();
  const hoursLeft = (new Date(r.inicio).getTime() - Date.now()) / 3600000;
  if (hoursLeft <= 0) return { ok: false, error: 'Esa cita ya pasó.' };
  const refundable = hoursLeft >= num_(s.horasCancelacion, 24);
  const wasConfirmed = r.estado === 'confirmada';
  const paidOutside = !r.paypalCaptura && Number(r.depositoRD) > 0 && (r.estado === 'por-confirmar' || !!r.depositoPagado) && /transferencia|efectivo/.test(r.metodoDeposito || '');
  const patch: any = { estado: 'cancelada', canceladaEn: new Date().toISOString(), canceladaPor: 'clienta' };
  patch.reembolso = !refundable ? 'no aplica (menos de ' + num_(s.horasCancelacion, 24) + ' h)'
    : r.paypalCaptura ? await tryRefund_(r.paypalCaptura, r.id + '-refund')
      : paidOutside ? 'pendiente: devolver por ' + (r.metodoDeposito === 'efectivo' ? 'efectivo' : 'transferencia') : 'sin depósito pagado';
  if (r.saldoCaptura) patch.reembolso += ' · saldo: ' + await tryRefund_(r.saldoCaptura, r.id + '-refund-saldo');
  if (refundable && wasConfirmed) { applyGift_(r, +1); applyBono_(r, +1); }
  updateRow_(found.index, patch);
  Object.keys(patch).forEach(function (k) { r[k] = patch[k]; });
  calendarCancel_(r, s);
  const refunded = /^reembolsado/.test(patch.reembolso) ? true : (/^pendiente/.test(patch.reembolso) ? 'manual' : false);
  notifyCancelled_(r, s, refunded);
  notifyWaitlist_(r.fecha);
  return { ok: true, refunded: refunded === true, refundManual: refunded === 'manual', appointment: publicRow_(r) };
}

export function reschedule_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: false, error: 'No encontramos esa cita.' };
  const r = found.row;
  const s = settings_();
  if (r.estado !== 'confirmada' && r.estado !== 'por-confirmar') return { ok: false, error: 'Esta cita ya no se puede cambiar.' };
  const max = changesMax_(s), used = Number(r.cambios) || 0;
  if (!max) return { ok: false, error: 'Para cambiar tu cita escríbenos por WhatsApp.' };
  if (used >= max) return { ok: false, error: max === 1 ? 'Ya cambiaste la fecha de esta cita una vez. Para otro cambio, escríbenos por WhatsApp.' : 'Ya usaste los ' + max + ' cambios de esta cita. Escríbenos por WhatsApp.' };
  const H = num_(s.horasCancelacion, 24);
  if ((new Date(r.inicio).getTime() - Date.now()) / 3600000 < H) return { ok: false, error: 'Faltan menos de ' + H + ' horas para tu cita: para cambiarla escríbenos por WhatsApp.' };
  if (!isDateKey_(d.date) || !/^\d{2}:\d{2}$/.test(d.time || '')) return { ok: false, error: 'Elige el nuevo día y la hora.' };
  if (d.date === r.fecha && d.time === r.hora) return { ok: false, error: 'Elige un horario distinto al actual.' };
  const minutes = Number(r.duracionMin) || 30;
  const problem = slotProblem_(schedule_(s), d.date, d.time, minutes);
  if (problem) return { ok: false, error: problem };
  const start = new Date(d.date + 'T' + d.time + ':00' + UTC_OFFSET);
  const end = new Date(start.getTime() + minutes * 60000);
  if (conflicts_(start, end, r.id).length) return { ok: false, error: 'Ese horario acaba de ocuparse. Elige otro, por favor.' };
  const before = whenText_(r);
  const oldDate = r.fecha;
  const patch: any = { fecha: d.date, hora: d.time, inicio: start.toISOString(), fin: end.toISOString(), reprogramadaDe: r.fecha + ' ' + r.hora, recordatorio: '', cambios: used + 1 };
  updateRow_(found.index, patch);
  Object.keys(patch).forEach(function (k) { r[k] = patch[k]; });
  calendarMove_(r, s);
  notifyRescheduled_(r, s, before);
  const a = mailAdminRescheduled_(r, s, before);
  safeMail_(adminTo_(s), a.subject, a.html, { tipo: 'aviso', ref: r.id });
  notifyWaitlist_(oldDate);
  return { ok: true, appointment: publicRow_(r) };
}

/* La clienta sube el comprobante (imagen o PDF) */
export async function transferProof_(d) {
  const found = findRow_(d.id);
  if (!found || !authorized_(found.row, d)) return { ok: false, error: 'No encontramos esa reserva.' };
  const r = found.row;
  if (r.metodoDeposito !== 'transferencia') return { ok: false, error: 'Esta reserva no se paga por transferencia.' };
  if (['retenida', 'expirada', 'por-confirmar'].indexOf(r.estado) < 0) return { ok: false, error: 'Esta reserva ya no está esperando un comprobante.' };
  const start = new Date(r.inicio), end = new Date(r.fin);
  const late = r.estado === 'expirada' || (r.estado === 'retenida' && new Date(r.retenidaHasta).getTime() < Date.now());
  if (late && conflicts_(start, end, r.id).length) return { ok: false, error: 'Se acabó el tiempo para subir el comprobante y el horario ya se ocupó. Escríbenos por WhatsApp y te ayudamos.' };
  if (start.getTime() < Date.now()) return { ok: false, error: 'La hora de esta cita ya pasó.' };
  const mime = String(d.mime || '');
  if (['image/jpeg', 'image/png', 'image/webp', 'application/pdf'].indexOf(mime) < 0) return { ok: false, error: 'Sube una foto (JPG o PNG) o un PDF del comprobante.' };
  const bytes = b64ToBytes(String(d.data || ''));
  if (!bytes.length) return { ok: false, error: 'El archivo está vacío.' };
  if (bytes.length > 8 * 1024 * 1024) return { ok: false, error: 'El archivo pesa más de 8 MB. Toma una captura de pantalla del comprobante.' };
  const accounts = transferInfo_(settings_()).accounts;
  const cuenta = accounts.filter(function (a) { return a.id === d.accountId; })[0] || (accounts.length === 1 ? accounts[0] : null);
  const key = clientKey_(r.correo, r.telefono, r.clienta);
  const ext = mime === 'application/pdf' ? '.pdf' : (mime === 'image/png' ? '.png' : '.jpg');
  const path = await putFile(PRIVATE_BUCKET, filePath(key, 'comprobante-' + r.id + ext), bytes, mime);
  const arc: any = {
    id: 'ARC-' + uuid().slice(0, 8).toUpperCase(), clave: key, tipo: 'comprobante', nombre: 'Comprobante ' + r.id + ext, mime: mime,
    driveId: path, citaId: r.id, fecha: todayKey_(), nota: 'Transferencia del depósito' + (cuenta ? ' · ' + cuenta.bank : '') + (d.ref ? ' · ref. ' + clean_(d.ref, 60) : ''), creada: new Date().toISOString(),
  };
  appendRow_('Archivos', arc);
  const replaced = r.estado === 'por-confirmar';
  const patch: any = { estado: 'por-confirmar', comprobanteId: arc.id, comprobanteEn: new Date().toISOString(), cuentaId: cuenta ? cuenta.id : '', transferenciaRef: clean_(d.ref, 60), retenidaHasta: '' };
  updateRow_(found.index, patch);
  Object.keys(patch).forEach(function (k) { r[k] = patch[k]; });
  const s = settings_();
  if (!replaced) { const m = mailTransferReceived_(r, s); safeMail_(r.correo, m.subject, m.html, { tipo: 'transferencia', ref: r.id }); }
  const a = mailAdminTransfer_(r, s, cuenta, replaced);
  safeMail_(adminTo_(s), a.subject, a.html, { tipo: 'aviso', ref: r.id, attachments: bytes.length < 5 * 1024 * 1024 ? [{ name: arc.nombre, mime: mime, data: String(d.data).replace(/^data:[^,]*,/, '') }] : null });
  return { ok: true, appointment: publicRow_(r) };
}

/* Guarda el cumpleaños de la reserva en la ficha de la clienta */
export function saveBirthday_(r) {
  const md = monthDay_(r.cumpleanos);
  if (!md) return;
  try {
    const key = clientKey_(r.correo, r.telefono, r.clienta);
    const c = readTable_('Clientas').filter(function (x) { return x.clave === key; })[0];
    if (c) { if (monthDay_(c.cumpleanos) !== md) updateTable_('Clientas', c._row, { cumpleanos: md, actualizada: new Date().toISOString() }); }
    else appendRow_('Clientas', { clave: key, nombre: r.clienta, telefono: r.telefono, correo: r.correo, notas: '', cumpleanos: md, actualizada: new Date().toISOString() });
  } catch (e) { /* no debe romper la reserva */ }
}

export function publicRow_(r): any {
  return {
    id: r.id, remote: true, status: r.estado,
    date: r.fecha, time: r.hora, start: r.inicio, end: r.fin,
    durationMinutes: Number(r.duracionMin) || 0,
    totalPrice: Number(r.totalRD) || 0,
    services: safeJson_(r.serviciosJson, []),
    payment: {
      subtotalRD: Number(r.subtotalRD) || Number(r.totalRD) || 0, discountRD: Number(r.descuentoRD) || 0, giftRD: Number(r.giftRD) || 0,
      depositRD: Number(r.depositoRD) || 0, depositUSD: r.depositoUSD, depositPaid: !!(r.paypalCaptura || r.depositoPagado),
      depositMethod: r.metodoDeposito || (r.paypalCaptura ? 'paypal' : ''),
      balanceRD: Number(r.saldoRD) || 0, balanceStatus: r.saldoEstado || 'pendiente', balanceMethod: r.saldoMetodo || '',
      refund: /^reembolsado/.test(r.reembolso || '') ? 'reembolsado' : (refundPending_(r) ? 'pendiente' : (r.reembolso ? 'no' : '')),
      transfer: r.metodoDeposito === 'transferencia' ? { deadline: r.estado === 'retenida' ? r.retenidaHasta : '', proof: !!r.comprobanteId, sentAt: r.comprobanteEn || '', account: r.cuentaId || '' } : null,
    },
    changes: { used: Number(r.cambios) || 0, max: changesMax_(settingsCached_()) },
    client: { name: r.clienta, email: r.correo },
    consent: consentState_(r),
    bono: r.bonoCodigo ? { code: r.bonoCodigo, amountRD: Number(r.bonoRD) || 0 } : null,
  };
}

export function adminRow_(r): any {
  const p = publicRow_(r);
  if (r.estado === 'retenida' && new Date(r.retenidaHasta).getTime() < Date.now()) p.status = 'expirada';
  p.client = { name: r.clienta, email: r.correo, phone: r.telefono, notes: r.nota };
  p.clientKey = clientKey_(r.correo, r.telefono, r.clienta);
  p.servicesText = r.servicios;
  p.createdAt = r.creada;
  p.createdBy = r.creadaPor || 'web';
  p.origin = r.origen || '';
  p.channel = r.canal || '';
  p.code = r.codigo || '';
  p.promoId = r.promoId || '';
  p.giftCode = r.giftCodigo || '';
  p.rescheduledFrom = r.reprogramadaDe || '';
  p.payment.depositPaidAt = r.depositoPagado;
  p.payment.balancePaidAt = r.saldoPagado;
  p.payment.refundDetail = r.reembolso;
  p.payment.paypalCapture = r.paypalCaptura;
  p.payment.balanceCapture = r.saldoCaptura;
  p.cancelledBy = r.canceladaPor;
  p.cancelledAt = r.canceladaEn;
  p.internalNote = r.notaInterna;
  p.holdUntil = r.estado === 'retenida' ? r.retenidaHasta : '';
  p.reminderAt = r.recordatorio || '';
  p.reviewAskedAt = r.resenaPedida || '';
  p.retouchNoticeAt = r.retoqueAviso || '';
  p.loyalty = r.fidelidad === 'si';
  p.birthday = r.cumpleanos || '';
  p.photoPermission = r.permisoFotos || '';
  p.proofId = r.comprobanteId || '';
  p.transferRef = r.transferenciaRef || '';
  p.accountId = r.cuentaId || '';
  p.reviewedAt = r.revisadaEn || '';
  p.refundPending = refundPending_(r);
  if (r.estado === 'retenida' && r.metodoDeposito === 'transferencia') p.holdUntil = r.retenidaHasta;
  return p;
}

/* MAJOBELLA · Catálogo público: servicios, horario, contenido de la web, promociones y formas de pago */
import { env_ } from './ctx.ts';
import { readOpt_ } from './db.ts';
import { categories_, serviceGroups_, servicesMap_, services_, settings_ } from './data.ts';
import { schedule_ } from './schedule.ts';
import { publicTemplates_ } from './consent-templates.ts';
import { promos_ } from './pricing.ts';
import { paypalEnv_, paypalConfigured_ } from './paypal.ts';
import { turnstileOn_ } from './security.ts';
import { num_, on_, todayKey_ } from './util.ts';

export function catalog_(): any {
  const s = settings_();
  const sch = schedule_(s);
  const today = todayKey_();
  const available = services_();
  return {
    ok: true,
    categories: categories_().filter((c) => available.some((x) => x.categoryId === c.id)),
    consentTemplates: publicTemplates_(),
    serviceGroups: serviceGroups_().filter((g) => available.some((x) => x.parentId === g.id)),
    services: available.map(function (x) {
      return { id: x.id, name: x.name, categoryId: x.categoryId, category: x.category,
        parentId: x.parentId, description: x.description, order: x.order,
        durationMinutes: x.durationMinutes, price: x.price, priceFrom: x.priceFrom, depositPercent: x.depositPercent, consentTemplateId: x.consentTemplateId };
    }),
    payments: {
      // No ofrecer PayPal hasta que la API tenga un par de credenciales configurado.
      enabled: paypalConfigured_(),
      paypalClientId: paypalConfigured_() ? env_('PAYPAL_CLIENT_ID') : '',
      usdRate: num_(s.tasaUSD, 63),
      depositPercent: num_(s.porcentajeDeposito, 50),
      holdMinutes: num_(s.minutosRetencion, 15),
      cancelHours: num_(s.horasCancelacion, 24),
      paypalEnv: paypalEnv_(),
    },
    schedule: {
      hours: sch.hours, blockedDates: sch.blocked,
      minNoticeHours: sch.minNotice, maxDaysAhead: sch.maxDays, slotStepMinutes: sch.step,
    },
    site: siteContent_(s),
    gallery: readOpt_('Galeria').filter(function (g) { return !/^no$/i.test(g.visible); })
      .sort(function (a, b) { return (Number(a.orden) || 0) - (Number(b.orden) || 0) || String(b.creada).localeCompare(String(a.creada)); })
      .map(function (g) { return { id: g.id, service: g.servicio, before: g.antesUrl, after: g.despuesUrl, text: g.texto }; }),
    reviews: readOpt_('Resenas').filter(function (r) { return !/^no$/i.test(r.visible); })
      .sort(function (a, b) { return (Number(a.orden) || 0) - (Number(b.orden) || 0) || String(b.fecha).localeCompare(String(a.fecha)); })
      .map(function (r) { return { id: r.id, author: r.autora, stars: Number(r.estrellas) || 5, text: r.texto, date: r.fecha }; }),
    packages: readOpt_('Paquetes').filter(function (k) { return !/^no$/i.test(k.activo) && /^s[ií]$/i.test(k.enWeb); }).map(packageOut_),
    loyalty: { enabled: on_(s.fidelidadActiva), every: num_(s.fidelidadVisitas, 5), kind: s.fidelidadTipo === 'monto' ? 'monto' : 'porcentaje', value: num_(s.fidelidadValor, 20) },
    waitlist: { enabled: on_(s.esperaActiva) },
    transfer: transferInfo_(s),
    reschedule: { max: changesMax_(s) },
    security: { turnstileSiteKey: turnstileOn_(s) ? String(s.turnstileSiteKey).trim() : '' },
    giftShop: {
      enabled: /^s[ií]$/i.test(s.tarjetasEnLinea || 'si') && paypalConfigured_(),
      min: num_(s.tarjetaMin, 500), max: num_(s.tarjetaMax, 30000), validDays: num_(s.tarjetaVenceDias, 365),
    },
    // Solo las promociones automáticas (los códigos no se publican)
    promos: promos_(today).filter(function (p) { return p.tipo === 'auto'; }).map(function (p) {
      return { id: p.id, name: p.nombre, services: p.servicios, kind: p.descuentoTipo, value: p.valor, until: p.hasta };
    }),
  };
}

export function siteContent_(s) {
  return {
    announcement: { active: !/^no$/i.test(s.anuncioActivo || 'si'), text: s.anuncioTexto || '', link: s.anuncioEnlace || '' },
    google: { rating: Number(String(s.googleRating || '').replace(',', '.')) || 0, count: Number(s.googleResenas) || 0, url: s.googleUrl || '', reviewUrl: s.googleResenaUrl || '' },
    majo: {
      title: s.majoTitulo || 'Conoce a Majo', text: s.majoTexto || '',
      certs: String(s.majoCerts || '').split('\n').map(function (x) { return x.trim(); }).filter(Boolean),
      photo: s.majoFotoUrl || '',
    },
    business: { name: s.negocioNombre || 'MAJOBELLA Beauty Studio', rnc: s.negocioRnc || '', email: s.negocioCorreo || '', address: s.direccion || '', whatsapp: s.whatsapp || '' },
  };
}

export function packageOut_(k) {
  const svc = servicesMap_()[k.servicio];
  const sessions = Number(k.sesiones) || 0, price = Number(k.precioRD) || 0;
  const regular = svc ? svc.price * sessions : 0;
  return {
    id: k.id, name: k.nombre, service: k.servicio, serviceName: svc ? svc.name : k.servicio, sessions: sessions, price: price,
    validDays: Number(k.venceDias) || 0, description: k.descripcion || '', regular: regular, savings: Math.max(0, regular - price),
  };
}

export function accountOut_(a) {
  return { id: a.id, bank: a.banco || '', type: a.tipo || '', number: a.numero || '', holder: a.titular || '', doc: a.documento || '', note: a.nota || '' };
}

export function transferInfo_(s) {
  const accounts = readOpt_('Cuentas').filter(function (a) { return !/^no$/i.test(a.activa) && a.numero; })
    .sort(function (a, b) { return (Number(a.orden) || 0) - (Number(b.orden) || 0); }).map(accountOut_);
  return { enabled: on_(s.transferenciaActiva) && accounts.length > 0, minutes: num_(s.transferenciaMinutos, 60), accounts: accounts };
}

export function changesMax_(s) {
  const t = String(s.cambiosMax == null ? '' : s.cambiosMax).trim();
  const n = Number(t);
  return t !== '' && isFinite(n) ? Math.max(0, Math.floor(n)) : 1;
}

export function refundPending_(r) { return /^(pendiente|devolver a mano)/.test(String(r.reembolso || '')); }

/* MAJOBELLA · Plantillas informadas y evaluación obligatoria antes del cobro.
   Solo Administración escribe plantillas; la clienta recibe únicamente plantillas activas asociadas a su servicio. */
import { readTable_, updateTable_, appendRow_ } from './db.ts';
import { needAdmin_ } from './security.ts';
import { clean_, safeJson_, uuid } from './util.ts';
import { adminData_ } from './admin.ts';
import { services_ } from './data.ts';

const BLOCK_MESSAGE = 'Gracias por compartir esta información con nosotros. Por tu bienestar y para brindarte una atención responsable, en este momento no será posible agendar esta sesión debido a la condición indicada en tu respuesta. Te invitamos a escribirnos para orientarte sobre los próximos pasos y, si corresponde, valorar una nueva fecha. Agradecemos mucho tu comprensión.';
export function allTemplates_() {
  return readTable_('PlantillasConsentimiento').map(r => ({
    id:String(r.id), nombre:String(r.nombre||''), descripcion:String(r.descripcion||''), texto:String(r.texto||''),
    estado:String(r.estado||'borrador'), preguntas:safeJson_(r.preguntas,[]), actualizado:String(r.actualizado||''),
  }));
}
export function publicTemplates_() {
  const used = new Set(services_().map(s=>String(s.consentTemplateId||'')).filter(Boolean));
  return allTemplates_().filter(t=>t.estado==='activo' && used.has(t.id))
    .map(t=>({id:t.id,nombre:t.nombre,descripcion:t.descripcion,texto:t.texto,preguntas:t.preguntas}));
}
export function adminSaveConsentTemplate_(d:any) {
  needAdmin_(d);
  const t=d.template||{};
  const id=clean_(t.id,40)||'cons-'+uuid().slice(0,12);
  if(!/^[a-z0-9_-]+$/i.test(id))throw new Error('Identificador de plantilla no válido.');
  const nombre=clean_(t.nombre,120),texto=clean_(t.texto,8000);
  if(!nombre || !texto)throw new Error('Escribe el nombre y el texto completo del consentimiento.');
  const estado=['activo','borrador','archivado'].includes(t.estado)?t.estado:'borrador';
  if(!Array.isArray(t.preguntas)||t.preguntas.length>30)throw new Error('La plantilla permite hasta 30 preguntas.');
  const seen=new Set<string>();
  const preguntas=t.preguntas.map((q:any,i:number)=>{
    const qid=clean_(q.id,40)||'p'+(i+1);
    const text=clean_(q.text,350);
    if(!text||seen.has(qid)||!/^[a-z0-9_-]+$/i.test(qid))throw new Error('Revisa las preguntas repetidas o sin texto.');
    seen.add(qid);
    const stopOn=['si','no'].includes(q.stopOn)?q.stopOn:'';
    return {id:qid,text,required:true,stopOn,
      stopMessage:stopOn?(clean_(q.stopMessage,900)||BLOCK_MESSAGE):''};
  });
  const rows=readTable_('PlantillasConsentimiento');
  const old=rows.find(x=>x.id===id);
  const patch={id,nombre,texto,descripcion:clean_(t.descripcion,800),estado,preguntas:JSON.stringify(preguntas),actualizado:new Date().toISOString()};
  if(old)updateTable_('PlantillasConsentimiento',old._row,patch);else appendRow_('PlantillasConsentimiento',patch);
  return adminData_(d);
}
export function evaluateConsent_(items:any[],d:any) {
  const ids=[...new Set(items.map(s=>String(s.consentTemplateId||'')).filter(Boolean))];
  if(!ids.length)return [];
  const templates=allTemplates_();
  const provided=Array.isArray(d.consents)?d.consents:[];
  return ids.map(id=>{
    const t=templates.find(x=>x.id===id && x.estado==='activo');
    if(!t)throw new Error('El consentimiento requerido no está disponible. Comunícate con el estudio antes de reservar.');
    const form=provided.find(x=>x && x.templateId===id);
    if(!form || form.accepted!==true)throw new Error('Revisa y acepta el consentimiento «'+t.nombre+'» antes de pagar.');
    const full=clean_(form.name,100);
    if(full.length<3)throw new Error('Escribe tu nombre completo en el consentimiento «'+t.nombre+'».');
    const answers=form.answers||{};
    if(!answers || typeof answers!=='object'||Array.isArray(answers))throw new Error('Responde las preguntas del consentimiento.');
    const normalized:any={};
    for(const q of t.preguntas){
      const v=String(answers[q.id]||'').toLowerCase();
      if(!['si','no'].includes(v))throw new Error('Responde todas las preguntas de «'+t.nombre+'».');
      if(q.stopOn===v)throw new Error(q.stopMessage||BLOCK_MESSAGE);
      normalized[q.id]={pregunta:q.text,respuesta:v};
    }
    return {templateId:t.id,templateName:t.nombre,templateText:t.texto,
      questions:normalized,accepted:true,name:full,signedAt:new Date().toISOString(),serviceIds:items.filter(s=>s.consentTemplateId===id).map(s=>s.id)};
  });
}

/* MAJOBELLA · Consentimiento digital: la clienta lo firma desde el enlace de su correo */
import { appendRow_ } from './db.ts';
import { findRow_, servicesMap_, settings_, settingsCached_, updateRow_ } from './data.ts';
import { CONSENT_QUESTIONS, DEFAULT_CONSENT, TZ } from './constants.ts';
import { mailConsentCopy_, mailUrl_, safeMail_ } from './mail.ts';
import { htmlToPdf_ } from './google.ts';
import { PRIVATE_BUCKET, filePath, putFile } from './storage.ts';
import { b64ToBytes, clean_, clientKey_, esc_, fmtDate, safeJson_, uuid, whenText_ } from './util.ts';

export function consentText_(s) { return String(s.consentimientoTexto || '').trim() || DEFAULT_CONSENT; }

export function consentState_(r): any {
  const svcs = servicesMap_();
  const needed = safeJson_(r.serviciosJson, []).some(function (x) { return svcs[x.id] && svcs[x.id].consent; });
  const url = needed && r.firmaToken ? mailUrl_(settingsCached_(), 'consentimiento.html?c=' + encodeURIComponent(r.id + '.' + r.firmaToken)) : '';
  return { needed: needed, signed: !!r.consentimiento, signedAt: r.consentimiento || '', url: url };
}

export function consentRow_(c) {
  const parts = String(c || '').split('.');
  if (parts.length !== 2) return null;
  const found = findRow_(parts[0]);
  if (!found || !found.row.firmaToken || found.row.firmaToken !== parts[1]) return null;
  return found;
}

export function consentInfo_(d) {
  const found = consentRow_(d.c);
  if (!found) return { ok: false, error: 'Este enlace no es válido. Pídenos uno nuevo por WhatsApp.' };
  const r = found.row;
  if (['confirmada', 'completada'].indexOf(r.estado) < 0) return { ok: false, error: 'Esta cita no está activa.' };
  const s = settings_();
  return {
    ok: true, id: r.id, name: r.clienta, services: r.servicios, when: whenText_(r), signed: !!r.consentimiento, signedAt: r.consentimiento || '',
    text: consentText_(s), questions: CONSENT_QUESTIONS, studio: s.direccion || '',
  };
}

export async function consentSign_(d) {
  const found = consentRow_(d.c);
  if (!found) return { ok: false, error: 'Este enlace no es válido. Pídenos uno nuevo por WhatsApp.' };
  const r = found.row;
  if (['confirmada', 'completada'].indexOf(r.estado) < 0) return { ok: false, error: 'Esta cita no está activa.' };
  if (r.consentimiento) return { ok: false, error: 'Ya firmaste el consentimiento de esta cita.' };
  const name = clean_(d.name, 100);
  if (name.length < 3) return { ok: false, error: 'Escribe tu nombre completo.' };
  if (!d.accept) return { ok: false, error: 'Debes aceptar el consentimiento para firmarlo.' };
  const sig = String(d.signature || '');
  if (!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(sig) || sig.length < 1500 || sig.length > 1500000) return { ok: false, error: 'Dibuja tu firma en el recuadro.' };
  const answers = d.answers || {};
  const missing = CONSENT_QUESTIONS.filter(function (q) { return ['si', 'no'].indexOf((answers[q.id] || {}).value) < 0; });
  if (missing.length) return { ok: false, error: 'Responde todas las preguntas de salud.' };
  const s = settings_();
  const when = new Date();
  const fotos = d.photos === 'si' ? 'si' : 'no';
  const html = consentPdfHtml_(r, s, name, answers, clean_(d.extra, 600), fotos, sig, when);
  // PDF con el conector de Google; si no está, se guarda la página HTML firmada
  const pdf = await htmlToPdf_(html, 'consentimiento');
  const isPdf = !!pdf;
  const fname = 'Consentimiento ' + r.fecha + ' · ' + r.clienta + (isPdf ? '.pdf' : '.html');
  const mime = isPdf ? 'application/pdf' : 'text/html';
  const bytes = isPdf ? b64ToBytes(pdf) : new TextEncoder().encode(html);
  const key = clientKey_(r.correo, r.telefono, r.clienta);
  const path = await putFile(PRIVATE_BUCKET, filePath(key, 'consentimiento-' + r.id + (isPdf ? '.pdf' : '.html')), bytes, mime);
  const arc: any = {
    id: 'ARC-' + uuid().slice(0, 8).toUpperCase(), clave: key, tipo: 'consentimiento', nombre: fname, mime: mime,
    driveId: path, citaId: r.id, fecha: r.fecha, nota: 'Firmado en la web', creada: when.toISOString(),
  };
  appendRow_('Archivos', arc);
  updateRow_(found.index, { consentimiento: when.toISOString(), consentimientoArchivo: arc.id, permisoFotos: fotos });
  r.consentimiento = when.toISOString();
  if (r.correo) { const m = mailConsentCopy_(r, s); safeMail_(r.correo, m.subject, m.html, { tipo: 'consentimiento', ref: r.id, attachments: isPdf ? [{ name: fname, mime: mime, data: pdf }] : null }); }
  return { ok: true, signedAt: r.consentimiento };
}

export function consentPdfHtml_(r, s, name, answers, extra, fotos, sig, when) {
  const F = "Georgia,'Times New Roman',serif";
  const qs = CONSENT_QUESTIONS.map(function (q) {
    const a = answers[q.id] || {};
    return '<tr><td style="padding:7px 8px 7px 0;border-bottom:1px solid #ddd">' + esc_(q.text) + '</td><td style="padding:7px 0;border-bottom:1px solid #ddd;width:34%"><b>' + (a.value === 'si' ? 'Sí' : 'No') + '</b>' +
      (a.value === 'si' && a.detail ? ' · ' + esc_(clean_(a.detail, 300)) : '') + '</td></tr>';
  }).join('');
  const text = consentText_(s).split(/\n\s*\n/).map(function (p) { return '<p style="margin:0 0 10px">' + esc_(p.trim()) + '</p>'; }).join('');
  const stamp = fmtDate(when, TZ, "d/M/yyyy, h:mm a");
  return '<html><head><meta charset="utf-8"></head><body style="font-family:' + F + ';color:#111;font-size:12px;line-height:1.5;margin:28px">' +
    '<p style="margin:0;font-size:22px;letter-spacing:6px">MAJOBELLA</p><p style="margin:0 0 18px;font-size:10px;letter-spacing:4px;color:#666">BEAUTY STUDIO</p>' +
    '<h1 style="font-weight:normal;font-size:20px;margin:0 0 12px;border-top:1px solid #111;padding-top:12px">Consentimiento informado</h1>' +
    '<table style="width:100%;border-collapse:collapse;margin-bottom:14px">' +
    '<tr><td style="color:#666;width:30%">Clienta</td><td>' + esc_(name) + '</td></tr>' +
    '<tr><td style="color:#666">Teléfono · correo</td><td>' + esc_(r.telefono || '—') + ' · ' + esc_(r.correo || '—') + '</td></tr>' +
    '<tr><td style="color:#666">Servicio</td><td>' + esc_(r.servicios) + '</td></tr>' +
    '<tr><td style="color:#666">Cita</td><td>' + esc_(whenText_(r)) + ' · ' + esc_(r.id) + '</td></tr></table>' +
    '<h2 style="font-weight:normal;font-size:15px;margin:14px 0 6px">Cuestionario de salud</h2><table style="width:100%;border-collapse:collapse">' + qs + '</table>' +
    (extra ? '<p style="margin:8px 0 0"><span style="color:#666">Otros datos:</span> ' + esc_(extra) + '</p>' : '') +
    '<h2 style="font-weight:normal;font-size:15px;margin:16px 0 6px">Consentimiento</h2>' + text +
    '<p style="margin:6px 0 0"><span style="color:#666">Publicar mis fotos de antes y después en la web y redes, sin mi nombre:</span> <b>' + (fotos === 'si' ? 'Sí autorizo' : 'No autorizo') + '</b></p>' +
    '<div style="margin-top:18px;border-top:1px solid #111;padding-top:10px"><img src="' + sig + '" style="height:90px"><p style="margin:4px 0 0">' + esc_(name) + '</p>' +
    '<p style="margin:2px 0 0;color:#666;font-size:10px">Firmado electrónicamente en la web de MAJOBELLA el ' + esc_(stamp) + ' (hora de Santo Domingo).</p></div>' +
    '</body></html>';
}

/* MAJOBELLA · Contexto de cada petición
   La API atiende varias peticiones a la vez en el mismo proceso, así que nada se guarda en variables
   globales: cada petición tiene su propio contexto (datos cargados, cambios pendientes, correos por
   enviar, usuaria que inició sesión…), al que se llega con cx(). */
import { AsyncLocalStorage } from 'node:async_hooks';

export type Row = Record<string, any> & { _row?: any };

/* Lo que la API necesita del mundo exterior. En producción lo arma functions/api/index.ts;
   en las pruebas, tests/harness.ts con una base local y servicios simulados. */
export interface Deps {
  sql: any;                                   // cliente postgres.js conectado a la base
  fetch: (url: string, init?: any) => Promise<any>;
  env: Record<string, string | undefined>;    // secretos y ajustes del servidor (nunca llegan al navegador)
}

export type Op =
  | { kind: 'insert'; table: string; row: Row }
  | { kind: 'update'; table: string; row: Row; patch: Record<string, any> }
  | { kind: 'delete'; table: string; row: Row }
  | { kind: 'upsert'; table: string; row: Row };

export interface OutMail { to: string; subject: string; html: string; text: string; attachments?: { name: string; mime: string; data: string }[]; log: Row | null; ref: string; tipo?: string; studio?: boolean }
export type OutTask =
  | { kind: 'mail'; mail: OutMail }
  | { kind: 'calendar.create'; citaId: string; event: any }
  | { kind: 'calendar.move'; eventId: string; start: string; end: string }
  | { kind: 'calendar.cancel'; eventId: string }
  | { kind: 'storage.remove'; bucket: string; paths: string[] };

export interface Ctx {
  deps: Deps;
  tables: Record<string, Row[]>;      // filas cargadas (formato de la lógica: todo como texto)
  ops: Op[];                          // cambios por guardar al final, en una sola transacción
  out: OutTask[];                     // correos, calendario y archivos por borrar: después de guardar
  svc: any; settings: any;            // memorias de esta petición
  user: { email: string; name: string } | null;   // sesión verificada (Supabase Auth)
  userToken: string;
  captcha: boolean | null;            // resultado de Cloudflare Turnstile (null = no se envió)
  captures: string[];                 // cobros hechos en esta petición (para avisar si algo falla al guardar)
  cronActive: boolean | null;
  seq: number;
}

const store = new AsyncLocalStorage<Ctx>();

export function newCtx(deps: Deps): Ctx {
  return { deps, tables: {}, ops: [], out: [], svc: null, settings: null, user: null, userToken: '', captcha: null, captures: [], cronActive: null, seq: 0 };
}
export function runWith<T>(c: Ctx, fn: () => Promise<T>): Promise<T> { return store.run(c, fn); }
export function cx(): Ctx {
  const c = store.getStore();
  if (!c) throw new Error('Sin contexto de petición.');
  return c;
}
export function env_(k: string): string { return String(cx().deps.env[k] || '').trim(); }

/* MAJOBELLA · Lecturas frecuentes: ajustes, servicios y reservas */
import { cx } from './ctx.ts';
import { readTable_, updateTable_ } from './db.ts';
import { DEFAULT_SETTINGS } from './constants.ts';
import { pctOrNull_ } from './util.ts';

export function settings_(): Record<string, string> {
  const out: Record<string, string> = {};
  DEFAULT_SETTINGS.forEach((x) => { out[x[0]] = x[1]; });
  readTable_('Ajustes').forEach((r) => { if (r.clave) out[String(r.clave).trim()] = String(r.valor == null ? '' : r.valor).trim(); });
  return out;
}
export function settingsCached_() { const c = cx(); if (!c.settings) c.settings = settings_(); return c.settings; }
export function resetCaches_() { const c = cx(); c.settings = null; c.svc = null; }

/* Un borrador se guarda en Administración pero no se expone en web, PWA ni app. */
export function published_(row: any) {
  const estado = String(row.estado || '').toLowerCase();
  return (estado ? estado === 'activo' : !/^no$/i.test(String(row.activo))) && !/^no$/i.test(String(row.activo));
}
/* Los grupos son contenedores, nunca opciones cobrables ni reservables. */
export function categories_() {
  return readTable_('Categorias').filter(published_)
    .sort((a, b) => (Number(a.orden) || 0) - (Number(b.orden) || 0))
    .map((r) => ({ id: String(r.id), name: String(r.nombre || r.id) }));
}
export function serviceGroups_() {
  const cats = new Set(categories_().map((c) => c.id));
  return readTable_('Servicios')
    .filter((r) => r.tipo === 'grupo' && published_(r) && cats.has(String(r.categoriaId || 'otros')))
    .sort((a, b) => (Number(a.orden) || 0) - (Number(b.orden) || 0))
    .map((r) => ({ id: String(r.id), name: String(r.nombre), categoryId: String(r.categoriaId || 'otros'), description: String(r.descripcion || ''), order: Number(r.orden) || 0 }));
}
export function services_() {
  const cats = categories_();
  const catNames = Object.fromEntries(cats.map((c) => [c.id, c.name]));
  const groups = serviceGroups_();
  const groupsById = Object.fromEntries(groups.map((g) => [g.id, g]));
  return readTable_('Servicios')
    .filter((r) => {
      if (!published_(r) || r.tipo === 'grupo') return false;
      const cid = String(r.categoriaId || 'otros');
      if (!catNames[cid]) return false;
      const parent = String(r.padreId || '');
      return !parent || (groupsById[parent] && groupsById[parent].categoryId === cid);
    })
    .sort((a, b) => (Number(a.orden) || 0) - (Number(b.orden) || 0))
    .map((r) => ({
      id: String(r.id).trim(), name: String(r.nombre).trim(), categoryId: String(r.categoriaId || 'otros'),
      category: catNames[String(r.categoriaId || 'otros')], parentId: String(r.padreId || ''),
      description: String(r.descripcion || ''), order: Number(r.orden) || 0,
      durationMinutes: Number(r.duracionMin) || 30, price: Number(r.precioRD) || 0,
      priceFrom: /^s[ií]$/i.test(String(r.precioDesde)), returnDays: Number(r.volverDias) || 0,
      depositPercent: pctOrNull_(r.depositoPct),
      retoqueDays: Number(r.retoqueDias) || 0, consent: /^s[ií]$/i.test(String(r.consentimiento)), consentTemplateId: String(r.consentTemplateId||''),
    }));
}
export function servicesMap_(): Record<string, any> {
  const c = cx();
  if (!c.svc) {
    c.svc = {};
    readTable_('Servicios').filter((r) => r.tipo !== 'grupo').forEach((r) => {
      c.svc[String(r.id).trim()] = { id: String(r.id).trim(), name: String(r.nombre).trim(), price: Number(r.precioRD) || 0, retoqueDays: Number(r.retoqueDias) || 0, consent: /^s[ií]$/i.test(String(r.consentimiento)), active: published_(r) };
    });
  }
  return c.svc;
}
export function catalogItems_(ids: string[]) {
  const catalog: Record<string, any> = {};
  services_().forEach((x) => { catalog[x.id] = x; });
  return ids.map((id) => catalog[id]);
}

export function rows_() { return readTable_('Reservas'); }
export function findRow_(id: any): { index: any; row: any } | null {
  if (!id) return null;
  const r = rows_().filter((x) => String(x.id) === String(id))[0];
  return r ? { index: r._row, row: r } : null;
}
export function updateRow_(index: any, patch: Record<string, any>) { updateTable_('Reservas', index, patch); }

/* MAJOBELLA · Acceso a la base de datos
   Cada petición:
     1. carga en memoria las tablas que necesita (una sola consulta);
     2. la lógica lee y cambia esa memoria (readTable_, appendRow_, updateTable_, deleteRow_);
     3. al final todos los cambios se guardan juntos en una transacción.
   Las acciones que tocan la agenda o los pagos se ejecutan una detrás de otra (candado de la base),
   así nunca se reservan dos citas en el mismo horario.
   Para la lógica cada valor es texto (como en la antigua hoja); en la base cada columna tiene su tipo real. */
import { cx, type Row } from './ctx.ts';
import { TABLE, COLS, TABLES, HEAVY, type Col } from './schema.ts';

const ISO = (c: string) => `to_char(${c} at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')`;
function selectExpr(c: Col): string {
  const x = c.col;
  switch (c.type) {
    case 'date': return `to_char(${x}, 'YYYY-MM-DD')`;
    case 'time': return `to_char(${x}, 'HH24:MI')`;
    case 'ts': return ISO(x);
    case 'bool': return `case when ${x} then 'si' when not ${x} then 'no' end`;
    case 'int': case 'num': case 'json': return `${x}::text`;
    default: return x;
  }
}
const ident = (s: string) => '"' + s.replace(/"/g, '""') + '"';

/* Consulta que trae varias tablas de una vez, cada una como un arreglo JSON */
function loadQuery(names: string[], where: Record<string, string>): string {
  const parts = names.map((n) => {
    const t = TABLE[n];
    const cols = [`row_id as "_row"`].concat(t.cols.map((c) => `${selectExpr(c)} as ${ident(c.key)}`)).join(', ');
    const w = where[n] ? ` where ${where[n]}` : '';
    const order = n === 'Correos' || n === 'Errores' ? ' order by row_id desc limit 300' : ' order by row_id';
    const inner = `select ${cols} from public.${t.table}${w}${order}`;
    return `${lit(n)}, coalesce((select json_agg(z) from (${inner}) z), '[]'::json)`;
  });
  return `select json_build_object(${parts.join(', ')}) as data`;
}

export interface LoadOpts { tables?: string[]; reservasRange?: { from: string; to: string } }

/* Carga las tablas de esta petición (por defecto, todas menos los historiales grandes) */
export async function loadTables(tx: any, opts: LoadOpts = {}) {
  const c = cx();
  const names = (opts.tables || TABLES.map((t) => t.name).filter((n) => !HEAVY.includes(n))).filter((n) => !c.tables[n]);
  if (!names.includes('Sistema') && !c.tables.Sistema) names.push('Sistema');
  if (!names.includes('Cache') && !c.tables.Cache) names.push('Cache');
  const where: Record<string, string> = { Cache: 'vence is null or vence > now()' };
  if (opts.reservasRange) {
    const { from, to } = opts.reservasRange;
    where.Reservas = `fin >= ${lit(from + 'T00:00:00-04:00')}::timestamptz and inicio <= ${lit(to + 'T23:59:59-04:00')}::timestamptz`;
  }
  const res = await tx.unsafe(loadQuery(names, where));
  const data = res[0].data;
  names.forEach((n) => {
    // Los historiales se cargan del más nuevo al más viejo (solo los últimos): se dejan en orden de llegada
    const rows = (data[n] || []) as Row[];
    if (n === 'Correos' || n === 'Errores') rows.reverse();
    rows.forEach((r) => { Object.keys(r).forEach((k) => { if (k !== '_row' && r[k] == null) r[k] = ''; }); });
    c.tables[n] = rows;
  });
}
function lit(s: string) { return "'" + String(s).replace(/'/g, "''") + "'"; }

/* ---- Lectura y escritura en la memoria de la petición ---- */

function loaded(name: string): Row[] {
  const c = cx();
  const t = c.tables[name];
  if (!t) throw new Error(`La tabla ${name} no se cargó para esta acción.`);
  return t;
}
export function isLoaded(name: string) { return !!cx().tables[name]; }

/* Filas como objetos { columna: texto, _row } (copias: se pueden modificar) */
export function readTable_(name: string): Row[] { return loaded(name).map((o) => Object.assign({}, o)); }
export function readOpt_(name: string): Row[] { try { return readTable_(name); } catch (e) { return []; } }

export function appendRow_(name: string, obj: Row) { return appendRowRef_(name, obj)._row; }
/* Igual, pero devuelve la fila (después de guardar, su _row pasa a ser el número real) */
export function appendRowRef_(name: string, obj: Row): Row {
  const c = cx();
  const cols = COLS[name];
  if (!cols) throw new Error('Tabla desconocida: ' + name);
  const row: Row = { _row: 'nuevo:' + (++c.seq) };
  Object.keys(cols).forEach((k) => { row[k] = String(obj[k] == null ? '' : obj[k]); });
  if (c.tables[name]) c.tables[name].push(row);
  c.ops.push({ kind: 'insert', table: name, row });
  return row;
}

/* Cambia columnas de una fila (por su _row) */
export function updateTable_(name: string, rowId: any, patch: Record<string, any>) {
  const c = cx();
  const cols = COLS[name];
  const keys = Object.keys(patch).filter((k) => cols[k]);
  if (!keys.length) return;
  const clean: Record<string, any> = {};
  keys.forEach((k) => { clean[k] = patch[k]; });
  const list = c.tables[name] || [];
  let row = list.find((o) => o._row === rowId);
  if (row) keys.forEach((k) => { row![k] = String(patch[k] == null ? '' : patch[k]); });
  else row = { _row: rowId };
  // Si la fila se creó en esta misma petición, basta con cambiar lo que se va a insertar
  const ins = c.ops.find((o) => o.kind === 'insert' && o.table === name && o.row._row === rowId);
  if (ins) { keys.forEach((k) => { ins.row[k] = String(patch[k] == null ? '' : patch[k]); }); return; }
  c.ops.push({ kind: 'update', table: name, row, patch: clean });
}

export function deleteRow_(name: string, rowId: any) {
  const c = cx();
  const list = c.tables[name] || [];
  const i = list.findIndex((o) => o._row === rowId);
  const row = i >= 0 ? list[i] : { _row: rowId };
  if (i >= 0) list.splice(i, 1);
  const ii = c.ops.findIndex((o) => o.kind === 'insert' && o.table === name && o.row._row === rowId);
  if (ii >= 0) { c.ops.splice(ii, 1); return; }
  c.ops.push({ kind: 'delete', table: name, row });
}

/* Inserta o reemplaza por la clave (tablas Sistema y Cache) */
function upsert_(name: string, key: string, obj: Row) {
  const c = cx();
  const list = c.tables[name] || (c.tables[name] = []);
  let row = list.find((o) => o.clave === key);
  if (row) Object.keys(obj).forEach((k) => { row![k] = String(obj[k] == null ? '' : obj[k]); });
  else { row = { _row: 'nuevo:' + (++c.seq), clave: key }; Object.keys(COLS[name]).forEach((k) => { if (k !== 'clave') row![k] = String(obj[k] == null ? '' : obj[k]); }); list.push(row); }
  c.ops = c.ops.filter((o) => !(o.kind === 'upsert' && o.table === name && o.row.clave === key));
  c.ops.push({ kind: 'upsert', table: name, row });
}

/* ---- Estado del sistema (antes: Propiedades del script) ---- */
export function sysGet(k: string): string { const r = (cx().tables.Sistema || []).find((x) => x.clave === k); return r ? String(r.valor || '') : ''; }
export function sysSet(k: string, v: any) { upsert_('Sistema', k, { clave: k, valor: String(v == null ? '' : v) }); }

/* ---- Memoria temporal con vencimiento (antes: CacheService) ---- */
export function cacheGet(k: string): string | null {
  const r = (cx().tables.Cache || []).find((x) => x.clave === k);
  if (!r) return null;
  if (r.vence && new Date(r.vence).getTime() <= Date.now()) return null;
  return String(r.valor);
}
export function cachePut(k: string, v: any, seconds: number) { upsert_('Cache', k, { clave: k, valor: String(v), vence: new Date(Date.now() + seconds * 1000).toISOString() }); }
export function cacheRemove(k: string) { const r = (cx().tables.Cache || []).find((x) => x.clave === k); if (r) deleteRow_('Cache', r._row); }

/* ---- Guardar ---- */

function toDb(col: Col, v: any): any {
  const t = v == null ? '' : String(v).trim();
  switch (col.type) {
    case 'text': return v == null || v === '' ? null : String(v);
    case 'int': { if (t === '') return null; const n = Number(t.replace(',', '.')); return isFinite(n) ? Math.round(n) : null; }
    case 'num': { if (t === '') return null; const n = Number(t.replace(',', '.')); return isFinite(n) ? t.replace(',', '.') : null; }
    case 'bool': if (/^(s[ií]|true|1)$/i.test(t)) return true; if (/^(no|false|0)$/i.test(t)) return false; return null;
    case 'date': return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null;
    case 'time': { const m = t.match(/^(\d{1,2}):(\d{2})/); return m ? `${m[1].padStart(2, '0')}:${m[2]}` : null; }
    case 'ts': { if (!t) return null; const d = new Date(t); return isNaN(d.getTime()) ? null : d.toISOString(); }
    case 'json': { if (t === '') return null; try { return { __json: JSON.parse(t) }; } catch (e) { return null; } }
  }
}
function dbObject(tx: any, name: string, row: Row, keys?: string[]) {
  const cols = COLS[name];
  const o: Record<string, any> = {};
  (keys || Object.keys(cols)).forEach((k) => {
    if (!cols[k] || !(k in row)) return;
    const v = toDb(cols[k], row[k]);
    o[cols[k].col] = v && typeof v === 'object' && '__json' in v ? tx.json(v.__json) : v;   // jsonb: con el ayudante de postgres.js
  });
  return o;
}

export async function commit(tx: any) {
  const c = cx();
  const ops = c.ops;
  c.ops = [];
  for (const op of ops) {
    const t = TABLE[op.table];
    if (op.kind === 'insert') {
      const o = dbObject(tx, op.table, op.row);
      const res = await tx`insert into ${tx('public.' + t.table)} ${tx(o)} returning row_id`;
      op.row._row = Number(res[0].row_id);
    } else if (op.kind === 'update') {
      if (typeof op.row._row !== 'number') continue;
      const o = dbObject(tx, op.table, op.patch, Object.keys(op.patch));
      if (Object.keys(o).length) await tx`update ${tx('public.' + t.table)} set ${tx(o)} where row_id = ${op.row._row}`;
    } else if (op.kind === 'delete') {
      if (typeof op.row._row === 'number') await tx`delete from ${tx('public.' + t.table)} where row_id = ${op.row._row}`;
    } else if (op.kind === 'upsert') {
      const o = dbObject(tx, op.table, op.row);
      const keys = Object.keys(o).filter((k) => k !== 'clave');
      await tx`insert into ${tx('public.' + t.table)} ${tx(o)} on conflict (clave) do update set ${tx(o, keys)}`;
    }
  }
  return ops.length;
}

/* MAJOBELLA · Avisos del sistema: se guardan en la tabla errores y se avisan por correo
   (como mucho uno cada 3 horas por tipo; los de cobros, siempre). */
import { cx } from './ctx.ts';
import { appendRow_, sysGet, sysSet } from './db.ts';
import { ERROR_TITLES, TZ } from './constants.ts';
import { clean_, esc_, fmtDate, plainText_, safeJson_ } from './util.ts';
import { settingsCached_ } from './data.ts';
import { adminTo_, layout_, mailUrl_ } from './mail.ts';

export function logError_(tipo: string, mensaje: string, ref: string, detalle: string, urgent?: boolean) {
  try {
    const now = Date.now();
    const key = 'ERR_' + tipo;
    let avisado = '';
    if (urgent || now - Number(sysGet(key) || 0) > 3 * 3600000) {
      let s: any = {};
      try { s = settingsCached_(); } catch (e) { s = {}; }
      const to = adminTo_(s);
      if (to) {
        const html = layout_(s, {
          kicker: 'Aviso del sistema', title: ERROR_TITLES[tipo] || 'Aviso del sistema',
          intro: esc_(mensaje),
          details: [['Cuándo', esc_(fmtDate(new Date(now), TZ, 'yyyy-MM-dd HH:mm'))], ref ? ['Referencia', esc_(ref)] : null, detalle ? ['Detalle', esc_(detalle)] : null].filter(Boolean),
          cta: { text: 'Ver en el panel', url: mailUrl_(s, 'admin.html#ajustes') },
          note: urgent ? 'Este aviso es importante: revísalo hoy.' : 'Si el problema se repite en las próximas 3 horas, quedará anotado en el panel sin enviar más correos.',
        });
        cx().out.push({ kind: 'mail', mail: { to, subject: '⚠ MAJOBELLA · ' + (ERROR_TITLES[tipo] || 'Aviso del sistema'), html, text: plainText_(html), log: null, ref: ref || '' } });
        avisado = new Date(now).toISOString();
        sysSet(key, String(now));
      }
    }
    appendRow_('Errores', { fecha: new Date(now).toISOString(), tipo, mensaje: clean_(mensaje, 600), ref: clean_(ref, 80), detalle: clean_(detalle, 600), avisado, resuelto: '' });
  } catch (e) { /* nunca romper la petición por anotar un error */ }
}

/* Si las tareas automáticas llevan más de 3 horas sin ejecutarse, se anota y se avisa */
export function heartbeat_() {
  try {
    const last = safeJson_(sysGet('LAST_AUTO'), null);
    if (!last || !last.at) return;
    const hours = (Date.now() - new Date(last.at).getTime()) / 3600000;
    if (hours > 3 && Date.now() - Number(sysGet('HB_LOGGED') || 0) > 3 * 3600000) {
      sysSet('HB_LOGGED', String(Date.now()));
      logError_('automatizacion', 'Las tareas automáticas (recordatorios, reseñas, cumpleaños) no se ejecutan desde hace ' + Math.floor(hours) + ' horas. Abre el panel para que se vuelvan a programar.', '', '');
    }
  } catch (e) { /* nada */ }
}

/* MAJOBELLA · Tarjetas de regalo y paquetes de sesiones (venta en la web con PayPal y en el estudio) */
