export function adminSellBono_(d) {
  needAdmin_(d);
  const k = readTable_('Paquetes').filter(function (x) { return x.id === d.paqueteId; })[0];
  if (!k) return { ok: false, error: 'Elige un paquete.' };
  const c = client_(d.client, false);
  if (!c.ok) return { ok: false, error: c.error };
  const monto = d.montoRD !== '' && d.montoRD != null ? Math.max(0, Math.round(Number(d.montoRD) || 0)) : Number(k.precioRD) || 0;
  const row = createBono_(k, c, { codigo: newBonoCode_(), montoRD: monto, metodoPago: ['efectivo', 'transferencia', 'paypal', 'cortesia'].indexOf(d.metodoPago) >= 0 ? d.metodoPago : 'efectivo' });
  if (d.notify && row.correo) { const m = mailBono_(row, settings_()); safeMail_(row.correo, m.subject, m.html, { tipo: 'paquete', ref: row.id }); }
  return { ok: true, bono: strip_(row) };
}

export function adminSaveBono_(d) {
  needAdmin_(d);
  const b = readTable_('Bonos').filter(function (x) { return x.id === d.id; })[0];
  if (!b) return { ok: false, error: 'No encontramos ese paquete.' };
  const patch: any = {};
  if (d.usadas != null) patch.usadas = Math.max(0, Math.min(Number(b.sesiones) || 0, Math.round(Number(d.usadas) || 0)));
  if (d.vence != null) patch.vence = isDateKey_(d.vence) ? d.vence : '';
  const used = patch.usadas != null ? patch.usadas : Number(b.usadas) || 0;
  if (d.estado === 'anulado') patch.estado = 'anulado';
  else if (d.estado === 'activo' || b.estado !== 'anulado') patch.estado = used >= (Number(b.sesiones) || 0) ? 'agotado' : 'activo';
  updateTable_('Bonos', b._row, patch);
  Object.keys(patch).forEach(function (k) { b[k] = patch[k]; });
  return { ok: true, bono: strip_(b) };
}

/* Compra de un paquete en la web (PayPal) */
export async function bonoOrder_(d) {
  const s = settings_();
  if (!human_(d, s)) return { ok: false, error: NOT_HUMAN };
  const k = readOpt_('Paquetes').filter(function (x) { return x.id === d.paqueteId && !/^no$/i.test(x.activo) && /^s[ií]$/i.test(x.enWeb); })[0];
  if (!k) return { ok: false, error: 'Ese paquete ya no está disponible.' };
  const c = client_(d.client, true);
  if (!c.ok) return { ok: false, error: c.error };
  const rate = num_(s.tasaUSD, 63);
  const usd = usd_(Number(k.precioRD) || 0, rate);
  const id = 'BON-' + uuid().slice(0, 6).toUpperCase();
  const order = await paypal_('post', '/v2/checkout/orders', {
    intent: 'CAPTURE',
    purchase_units: [{ reference_id: id, custom_id: id, invoice_id: id, description: ('Paquete MAJOBELLA · ' + k.nombre).slice(0, 127), amount: { currency_code: 'USD', value: usd.toFixed(2) } }],
    application_context: appContext_(d, s),
  }, id + '-order');
  const row = createBono_(k, c, { estado: 'pendiente', metodoPago: 'paypal', paypalOrden: order.id });
  return { ok: true, id: row.id, orderId: order.id, approveUrl: approveUrl_(order), montoUSD: usd.toFixed(2), usdRate: rate };
}

export async function bonoCapture_(d) {
  const b = readTable_('Bonos').filter(function (x) { return x.id === d.id; })[0];
  if (!b || b.paypalOrden !== d.orderId) return { ok: false, error: 'No encontramos esa compra.' };
  if (b.estado !== 'pendiente' && b.paypalCaptura) return { ok: true, bono: bonoOut_(b) };
  const cap = firstCapture_(await paypal_('post', '/v2/checkout/orders/' + encodeURIComponent(d.orderId) + '/capture', {}, b.id + '-capture'));
  if (!cap || cap.status !== 'COMPLETED') return { ok: false, error: 'PayPal no completó el pago. No se te cobró.' };
  try { return bonoActivate_(b, cap); } catch (err) { return paidButFailed_('el paquete ' + b.nombre + ' (' + b.id + ')', cap.id, b.id, err); }
}

export function bonoActivate_(b, cap) {
  const k = readTable_('Paquetes').filter(function (x) { return x.id === b.paqueteId; })[0] || {};
  const today = todayKey_();
  const patch: any = { codigo: newBonoCode_(), estado: 'activo', vendida: today, vence: Number(k.venceDias) > 0 ? addDaysKey_(today, Number(k.venceDias)) : '', paypalCaptura: cap.id };
  updateTable_('Bonos', b._row, patch);
  Object.keys(patch).forEach(function (x) { b[x] = patch[x]; });
  const s = settings_();
  const m = mailBono_(b, s);
  safeMail_(b.correo, m.subject, m.html, { tipo: 'paquete', ref: b.id });
  safeMail_(adminTo_(s), 'Paquete vendido en la web · ' + b.nombre, layout_(s, {
    kicker: 'Paquete vendido', title: b.clienta,
    details: [['Paquete', esc_(b.nombre)], ['Monto', 'RD$ ' + money_(b.montoRD)], ['Código', esc_(b.codigo)], ['Teléfono', esc_(b.telefono)], ['Correo', esc_(b.correo)]],
    cta: { text: 'Abrir dashboard', url: mailUrl_(s, 'admin.html#promos') },
  }), { tipo: 'aviso', ref: b.id });
  return { ok: true, bono: bonoOut_(b) };
}

export function bonoOut_(b): any {
  const svc = servicesMap_()[b.servicio];
  return { codigo: b.codigo, nombre: b.nombre, sesiones: Number(b.sesiones) || 0, servicio: b.servicio, serviceName: svc ? svc.name : b.servicio, vence: b.vence };
}

/* La app consulta el saldo de las tarjetas de regalo y paquetes que la clienta guardó (quien tiene el código puede verlo) */
export function walletLookup_(d) {
  if (limited_(d)) return { ok: false, error: TOO_MANY };
  const codes = (d.codes || []).slice(0, 20).map(normCode_).filter(Boolean);
  const items = walletItems_(codes);
  if (items.some(function (x) { return x.type === 'unknown'; })) noteFail_(d);
  return { ok: true, items: items };
}

export function walletItems_(codes) {
  const today = todayKey_();
  const svcs = servicesMap_();
  const items = codes.map(function (c) {
    const g = findGift_(c);
    if (g && g.estado !== 'pendiente') {
      const expired = !!(g.vence && today > g.vence);
      return { code: c, type: 'gift', amountRD: Number(g.montoRD) || 0, balanceRD: Number(g.saldoRD) || 0, to: g.para || '', from: g.comprador || '', message: g.mensaje || '', expires: g.vence || '', status: g.estado === 'anulada' ? 'anulada' : expired ? 'vencida' : (Number(g.saldoRD) > 0 ? 'activa' : 'agotada') };
    }
    const b = findBono_(c);
    if (b && b.estado !== 'pendiente') {
      const expired = !!(b.vence && today > b.vence);
      const svc = svcs[b.servicio];
      return { code: c, type: 'package', name: b.nombre, service: b.servicio, serviceName: svc ? svc.name : b.servicio, sessions: Number(b.sesiones) || 0, used: Number(b.usadas) || 0, expires: b.vence || '', status: b.estado === 'anulado' ? 'anulado' : expired ? 'vencido' : b.estado };
    }
    return { code: c, type: 'unknown', status: 'no encontrado' };
  });
  return items;
}

export function walletCodesFor_(email) {
  const e = String(email || '').trim().toLowerCase();
  if (!e) return [];
  const codes = [];
  readOpt_('Tarjetas').forEach(function (g) {
    if (g.estado === 'pendiente' || !g.codigo) return;
    if ([g.correoComprador, g.correoPara].map(function (x) { return String(x || '').toLowerCase(); }).indexOf(e) >= 0) codes.push(normCode_(g.codigo));
  });
  readOpt_('Bonos').forEach(function (b) {
    if (b.estado !== 'pendiente' && b.codigo && String(b.correo || '').toLowerCase() === e) codes.push(normCode_(b.codigo));
  });
  return codes.filter(function (c, i) { return codes.indexOf(c) === i; });
}

export function myWallet_(d) {
  const u = verifyIdToken_(d.idToken);
  if (!u) return { ok: false, error: 'Tu sesión expiró. Vuelve a iniciar sesión.' };
  return { ok: true, items: walletItems_(walletCodesFor_(u.email)) };
}

/* Envía sus códigos al correo (así solo la dueña del correo los ve). Siempre responde igual. */
export function walletEmail_(d) {
  const s = settings_();
  const email = clean_(d.email, 120).toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return { ok: false, error: 'Escribe un correo válido.' };
  if (!human_(d, s)) return { ok: false, error: NOT_HUMAN };
  const key = 'we_' + hash_(email).slice(0, 32);
  const gkey = 'we_g_' + Math.floor(Date.now() / 3600000);
  const sent: any = { ok: true, message: 'Si tienes tarjetas o paquetes con ese correo, te los enviamos en un momento. Revisa también la carpeta de spam.' };
  if (cacheGet(key)) return sent;
  const total = Number(cacheGet(gkey) || 0);
  if (total >= 60) return sent;
  cachePut(key, '1', 600);
  cachePut(gkey, String(total + 1), 3700);
  const items = walletItems_(walletCodesFor_(email)).filter(function (x) { return x.type !== 'unknown'; });
  if (items.length) { const m = mailWallet_(email, items, s); safeMail_(email, m.subject, m.html, { tipo: 'billetera', ref: email }); }
  return sent;
}

/* MAJOBELLA · Conector de Google (Gmail, Google Calendar y PDF)
   Un pequeño script de Apps Script en la cuenta del estudio (backend/google-relay/Relay.gs) envía los
   correos desde su Gmail, agenda las citas en su Google Calendar y convierte el consentimiento a PDF.
   La API le habla con una clave compartida (GOOGLE_RELAY_URL y GOOGLE_RELAY_KEY en los secretos).
   Alternativa para el correo: Resend (RESEND_API_KEY y MAIL_FROM). */
import { cx, env_ } from './ctx.ts';
import { msg_ } from './util.ts';
import { describe_ } from './mail.ts';

export function relayOn_() { return !!(env_('GOOGLE_RELAY_URL') && env_('GOOGLE_RELAY_KEY')); }

export async function relay_(ops: any[]): Promise<any[]> {
  const res = await cx().deps.fetch(env_('GOOGLE_RELAY_URL'), {
    method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify({ key: env_('GOOGLE_RELAY_KEY'), ops }),
    redirect: 'follow',
  });
  const text = await res.text();
  let data: any = null;
  try { data = JSON.parse(text); } catch (e) { throw new Error('El conector de Google no respondió bien (' + res.status + ').'); }
  if (!data.ok) throw new Error('Conector de Google: ' + (data.error || 'error'));
  return data.results || [];
}

/* ---- Google Calendar: se agenda después de guardar la cita ---- */
function calendarOn_(s: any) { return relayOn_() && !!String(s.calendarioId || '').trim(); }

export function calendarCreate_(r: any, s: any) {
  if (!calendarOn_(s)) return '';
  cx().out.push({
    kind: 'calendar.create', citaId: r.id,
    event: {
      calendarId: String(s.calendarioId).trim(), title: 'MAJOBELLA · ' + r.servicios + ' · ' + r.clienta, start: r.inicio, end: r.fin,
      description: describe_(r, s), location: s.direccion || '', guest: r.correo && /^s[ií]$/i.test(s.invitarClienta) ? r.correo : '',
    },
  });
  return '';
}
export function calendarMove_(r: any, s: any) {
  if (!calendarOn_(s) || !r.eventoId) return;
  cx().out.push({ kind: 'calendar.move', eventId: r.eventoId, start: r.inicio, end: r.fin });
}
export function calendarCancel_(r: any, s: any) {
  if (!calendarOn_(s) || !r.eventoId) return;
  cx().out.push({ kind: 'calendar.cancel', eventId: r.eventoId });
}
export function calendarIdFor_(s: any) { return String(s.calendarioId || '').trim(); }

/* ---- HTML → PDF (consentimiento firmado). Sin conector se guarda el HTML. ---- */
export async function htmlToPdf_(html: string, name: string): Promise<string | null> {
  if (!relayOn_()) return null;
  try {
    const r = await relay_([{ type: 'pdf', html, name }]);
    return r[0] && r[0].ok && r[0].data ? r[0].data : null;
  } catch (e) { void msg_(e); return null; }
}

/* MAJOBELLA · Pasar los datos de la hoja de Google a la base de datos
   El script anterior de Apps Script (función migrarABaseDeDatos) envía cada pestaña y cada archivo de Drive
   a esta acción, con la clave IMPORT_KEY (secreto de Supabase, solo para la migración).
   Se puede repetir sin duplicar: las filas con el mismo id se actualizan. */
import { env_ } from './ctx.ts';
import { appendRow_, readOpt_, readTable_, updateTable_ } from './db.ts';
import { TABLE } from './schema.ts';
import { PRIVATE_BUCKET, PUBLIC_BUCKET, filePath, publicUrl, putFile } from './storage.ts';
import { b64ToBytes, clean_, normPhone_, properName_ } from './util.ts';

/* Al importar, nombres, teléfonos y correos quedan con el mismo formato que los nuevos */
const NORMALIZE: Record<string, Record<string, 'name' | 'phone' | 'email'>> = {
  Reservas: { clienta: 'name', telefono: 'phone', correo: 'email' },
  Clientas: { nombre: 'name', telefono: 'phone', correo: 'email' },
  Espera: { clienta: 'name', telefono: 'phone', correo: 'email' },
  Bonos: { clienta: 'name', telefono: 'phone', correo: 'email' },
  Tarjetas: { comprador: 'name', para: 'name', correoComprador: 'email', correoPara: 'email' },
};
function normalize(name: string, r: any) {
  const plan = NORMALIZE[name];
  if (!plan) return r;
  Object.keys(plan).forEach((col) => {
    const v = String(r[col] || '');
    if (!v) return;
    if (name === 'Reservas' && col === 'clienta' && /^Bloque/.test(v)) return;
    if (plan[col] === 'name') r[col] = properName_(v);
    else if (plan[col] === 'email') r[col] = v.trim().toLowerCase();
    else { const ph = normPhone_(v); if (ph.ok) r[col] = ph.value; }
  });
  return r;
}

const IMPORTABLE = ['Ajustes', 'Servicios', 'Bloqueos', 'Clientas', 'Archivos', 'Promociones', 'Tarjetas', 'Gastos', 'Galeria', 'Resenas', 'Paquetes', 'Bonos', 'Espera', 'Cuentas', 'Reservas', 'Correos', 'Errores'];

function checkKey(d: any) {
  const key = env_('IMPORT_KEY');
  if (!key || d.key !== key) throw new Error('No autorizado para importar.');
}

export async function importData_(d: any) {
  checkKey(d);
  if (d.file) return importFile_(d);
  const out: Record<string, { nuevas: number; actualizadas: number }> = {};
  Object.keys(d.tables || {}).forEach((name) => {
    if (IMPORTABLE.indexOf(name) < 0) return;
    const t = TABLE[name];
    const rows = (d.tables[name] || []) as any[];
    const res = { nuevas: 0, actualizadas: 0 };
    const existing = t.pk ? readOpt_(name) : [];
    rows.forEach((raw) => {
      const r: any = {};
      Object.keys(raw).forEach((k) => { r[k] = raw[k] == null ? '' : String(raw[k]); });
      normalize(name, r);
      if (t.pk) {
        const id = String(r[t.pk] || '').trim();
        if (!id) return;
        const have = existing.find((x) => String(x[t.pk!]) === id);
        if (have) { updateTable_(name, have._row, r); res.actualizadas++; return; }
      }
      appendRow_(name, r);
      res.nuevas++;
    });
    out[name] = res;
  });
  return { ok: true, result: out };
}

/* Un archivo de Drive → Storage. tipo: 'archivo' (ficha privada) | 'galeria' (antes/después) | 'majo' (foto pública) */
async function importFile_(d: any) {
  const f = d.file;
  const bytes = b64ToBytes(String(f.data || ''));
  if (!bytes.length) return { ok: false, error: 'Archivo vacío.' };
  const mime = String(f.mime || 'application/octet-stream');
  if (f.tipo === 'archivo') {
    const row = readTable_('Archivos').find((x) => x.id === f.id);
    if (!row) return { ok: false, error: 'No existe la ficha ' + f.id };
    const path = await putFile(PRIVATE_BUCKET, filePath(row.clave || 'importado', clean_(row.nombre || f.id, 80)), bytes, mime);
    updateTable_('Archivos', row._row, { driveId: path });
    return { ok: true, path };
  }
  if (f.tipo === 'galeria') {
    const row = readTable_('Galeria').find((x) => x.id === f.id);
    if (!row) return { ok: false, error: 'No existe la foto ' + f.id };
    const ext = mime === 'image/png' ? '.png' : '.jpg';
    const path = await putFile(PUBLIC_BUCKET, 'galeria/' + f.id + '-' + f.lado + ext, bytes, mime);
    updateTable_('Galeria', row._row, f.lado === 'antes' ? { antesId: path, antesUrl: publicUrl(path) } : { despuesId: path, despuesUrl: publicUrl(path) });
    return { ok: true, path };
  }
  if (f.tipo === 'majo') {
    const path = await putFile(PUBLIC_BUCKET, 'web/majo-importada' + (mime === 'image/png' ? '.png' : '.jpg'), bytes, mime);
    const row = readTable_('Ajustes').find((x) => x.clave === 'majoFotoUrl');
    if (row) updateTable_('Ajustes', row._row, { valor: publicUrl(path) }); else appendRow_('Ajustes', { clave: 'majoFotoUrl', valor: publicUrl(path), 'qué es': '' });
    return { ok: true, path };
  }
  return { ok: false, error: 'Tipo de archivo no válido.' };
}

